-- i18n: en/es translations of every "quimica" question
-- (203 questions x 2 locales = 406 rows). Only writes
-- question_translations; questions (the pt-BR original, including
-- correct_index) is never touched.
--
-- options keep exactly the original order: correct_index is positional and
-- is always read from the original row. The join below also refuses any row
-- whose option count differs from the original, so a bad line can never
-- turn into a question with the wrong answer marked.
--
-- Keyed by the real questions.id read from the live database. Idempotent
-- (on conflict do update). Check afterwards with i18n_questions_checkup.sql.

insert into question_translations (question_id, locale, prompt, options, explanation)
select v.id::uuid, v.locale, v.prompt, v.options, v.explanation
from (values
  ('f334b93b-e0e3-4bdd-8db9-d9fd6de58726', 'en',
   'Stoichiometry is the branch of chemistry that studies:',
   array['The quantitative relationships between reactants and products in a chemical reaction', 'Only the physical properties of the elements', 'Exclusively the electronic structure of atoms', 'The classification of organic compounds'],
   'Stoichiometry calculates the proportions of mass, moles or volume between the substances involved in a chemical reaction.'),
  ('f334b93b-e0e3-4bdd-8db9-d9fd6de58726', 'es',
   'La estequiometría es la rama de la química que estudia:',
   array['Las relaciones cuantitativas entre reactivos y productos en una reacción química', 'Solo las propiedades físicas de los elementos', 'Exclusivamente la estructura electrónica de los átomos', 'La clasificación de los compuestos orgánicos'],
   'La estequiometría calcula las proporciones de masa, mol o volumen entre las sustancias que participan en una reacción química.'),
  ('e1c96ce7-3e3d-4c84-903b-be2ab8f1ebe1', 'en',
   'The mole is defined as the amount of substance containing a number of particles equal to:',
   array['The Avogadro constant, approximately 6.02 × 10²³', 'Exactly 1000 particles', 'The element''s atomic number', 'The substance''s molecular mass, in grams'],
   'One mole corresponds to 6.02 × 10²³ particles, the so-called Avogadro number.'),
  ('e1c96ce7-3e3d-4c84-903b-be2ab8f1ebe1', 'es',
   'El mol se define como la cantidad de sustancia que contiene un número de partículas igual a:',
   array['La constante de Avogadro, aproximadamente 6,02 × 10²³', 'Exactamente 1000 partículas', 'El número atómico del elemento', 'La masa molecular de la sustancia, en gramos'],
   'Un mol corresponde a 6,02 × 10²³ partículas, el llamado número de Avogadro.'),
  ('7131a2ab-fba7-4c41-aa46-f8c3d1e04e66', 'en',
   'In the balanced equation 2H₂ + O₂ → 2H₂O, how many moles of water are produced from 4 moles of hydrogen gas (H₂), assuming enough oxygen?',
   array['4 moles', '2 moles', '8 moles', '1 mole'],
   'By the proportion in the balanced equation (2 moles of H₂ to 2 moles of H₂O), 4 moles of H₂ produce 4 moles of H₂O.'),
  ('7131a2ab-fba7-4c41-aa46-f8c3d1e04e66', 'es',
   'En la ecuación balanceada 2H₂ + O₂ → 2H₂O, ¿cuántos moles de agua se producen a partir de 4 moles de gas hidrógeno (H₂), suponiendo oxígeno suficiente?',
   array['4 moles', '2 moles', '8 moles', '1 mol'],
   'Según la proporción de la ecuación balanceada (2 moles de H₂ por 2 moles de H₂O), 4 moles de H₂ producen 4 moles de H₂O.'),
  ('d902643a-8a0a-4543-963e-45d2a8778b51', 'en',
   'Lavoisier''s Law of Conservation of Mass states that, in a chemical reaction in a closed system:',
   array['The total mass of the reactants equals the total mass of the products', 'The mass of the products is always greater than that of the reactants', 'The mass of the reactants is always greater than that of the products', 'Mass has nothing to do with the chemical reaction'],
   'According to Lavoisier, "in nature nothing is created, nothing is lost, everything is transformed": the total mass is conserved.'),
  ('d902643a-8a0a-4543-963e-45d2a8778b51', 'es',
   'La Ley de Conservación de la Masa, formulada por Lavoisier, establece que, en una reacción química en sistema cerrado:',
   array['La masa total de los reactivos es igual a la masa total de los productos', 'La masa de los productos es siempre mayor que la de los reactivos', 'La masa de los reactivos es siempre mayor que la de los productos', 'La masa no tiene ninguna relación con la reacción química'],
   'Según Lavoisier, "en la naturaleza nada se crea, nada se pierde, todo se transforma": la masa total se conserva.'),
  ('0be76e49-ad44-413f-8e74-bf34816b13f7', 'en',
   'The limiting reactant of a chemical reaction is the one that:',
   array['Runs out first, determining the maximum amount of product formed', 'Is always present in the largest amount in the reaction', 'Never actually takes part in the reaction', 'Is formed at the end of the reaction, not consumed'],
   'The limiting reactant determines the maximum amount of product that can be formed, since it is completely consumed first.'),
  ('0be76e49-ad44-413f-8e74-bf34816b13f7', 'es',
   'El reactivo limitante de una reacción química es aquel que:',
   array['Se agota primero y determina la cantidad máxima de producto formado', 'Está siempre en mayor cantidad en la reacción', 'Nunca participa efectivamente en la reacción', 'Se forma al final de la reacción, en lugar de consumirse'],
   'El reactivo limitante determina la cantidad máxima de productos que puede formarse, pues se consume por completo primero.'),
  ('199ab8f7-cbb2-46ec-9e0d-6c8e27cca472', 'en',
   'The molar mass of a substance is numerically equal to its molecular mass, but expressed in:',
   array['Grams per mole (g/mol)', 'Only atomic mass units (u), with no other unit', 'Liters', 'Moles per liter'],
   'Molar mass converts molecular mass (in u) into a practical quantity, expressed in g/mol.'),
  ('199ab8f7-cbb2-46ec-9e0d-6c8e27cca472', 'es',
   'La masa molar de una sustancia es numéricamente igual a su masa molecular, pero expresada en:',
   array['Gramos por mol (g/mol)', 'Solo unidades de masa atómica (u), sin otra unidad', 'Litros', 'Moles por litro'],
   'La masa molar convierte la masa molecular (en u) en una magnitud práctica, expresada en g/mol.'),
  ('e1d36acc-5368-48d3-a42d-b01822585c1b', 'en',
   'In industrial practice, the yield of a chemical reaction is usually below 100% mainly because of:',
   array['Side reactions, process losses and incomplete reversible reactions', 'An unavoidable error in the Law of Conservation of Mass', 'The complete absence of limiting reactants', 'The impossibility of any chemical reaction going to completion'],
   'Factors such as side reactions, physical losses and incomplete chemical equilibria reduce the actual yield compared with the theoretical one.'),
  ('e1d36acc-5368-48d3-a42d-b01822585c1b', 'es',
   'En la práctica industrial, el rendimiento de una reacción química suele ser inferior al 100% principalmente debido a:',
   array['Reacciones secundarias, pérdidas en el proceso y reacciones reversibles incompletas', 'Un error inevitable en la Ley de Conservación de la Masa', 'La ausencia total de reactivos limitantes', 'La imposibilidad de que cualquier reacción química se complete'],
   'Factores como las reacciones paralelas, las pérdidas físicas y los equilibrios químicos incompletos reducen el rendimiento real respecto al teórico.'),
  ('615aec69-c775-454a-9084-fd4f3c8947dc', 'en',
   'At standard temperature and pressure (STP), the molar volume of an ideal gas is approximately:',
   array['22.4 liters per mole', '1 liter per mole', '6.02 liters per mole', '100 liters per mole'],
   'At STP (0°C and 1 atm), any ideal gas occupies approximately 22.4 liters per mole.'),
  ('615aec69-c775-454a-9084-fd4f3c8947dc', 'es',
   'En condiciones normales de presión y temperatura (CNPT), el volumen molar de un gas ideal es aproximadamente:',
   array['22,4 litros por mol', '1 litro por mol', '6,02 litros por mol', '100 litros por mol'],
   'En CNPT (0°C y 1 atm), cualquier gas ideal ocupa aproximadamente 22,4 litros por mol.'),
  ('28487de7-ac1e-466c-8be6-2c3195eceb62', 'en',
   'Electrons are subatomic particles located:',
   array['In the electron cloud, around the nucleus, with a negative electric charge', 'In the nucleus, with a positive electric charge', 'In the nucleus, with no electric charge', 'Outside the atom, in any fixed position'],
   'Electrons orbit the nucleus in the electron cloud and have a negative electric charge.'),
  ('28487de7-ac1e-466c-8be6-2c3195eceb62', 'es',
   'Los electrones son partículas subatómicas ubicadas:',
   array['En la corteza electrónica, alrededor del núcleo, con carga eléctrica negativa', 'En el núcleo, con carga eléctrica positiva', 'En el núcleo, sin carga eléctrica', 'Fuera del átomo, en cualquier posición fija'],
   'Los electrones orbitan el núcleo en la corteza electrónica y tienen carga eléctrica negativa.'),
  ('b90b4b2d-6739-4ed4-85f8-7a60bfe7de44', 'en',
   'The electrons located in the outermost shell of an atom are called:',
   array['Valence electrons', 'Free electrons', 'Core electrons', 'Neutral electrons'],
   'Valence electrons, in the outermost shell, are mainly responsible for chemical bonds.'),
  ('b90b4b2d-6739-4ed4-85f8-7a60bfe7de44', 'es',
   'Los electrones ubicados en la capa más externa de un átomo se llaman:',
   array['Electrones de valencia', 'Electrones libres', 'Electrones internos', 'Electrones neutros'],
   'Los electrones de valencia, en la capa más externa, son los principales responsables de los enlaces químicos.'),
  ('4682a21b-02cc-405b-b096-24aa80cf7179', 'en',
   'A cation forms when an atom:',
   array['Loses one or more electrons', 'Gains one or more electrons', 'Loses one or more protons', 'Gains one or more neutrons'],
   'Losing electrons results in a positively charged ion, called a cation.'),
  ('4682a21b-02cc-405b-b096-24aa80cf7179', 'es',
   'Un catión se forma cuando un átomo:',
   array['Pierde uno o más electrones', 'Gana uno o más electrones', 'Pierde uno o más protones', 'Gana uno o más neutrones'],
   'La pérdida de electrones da como resultado un ion de carga positiva, llamado catión.'),
  ('1789d6b2-9999-406d-b100-1b1a9c7ea9da', 'en',
   'Compared with that of the proton, the mass of the electron is:',
   array['Much smaller, about 1836 times smaller', 'Approximately equal', 'Much larger', 'Twice the mass of the proton'],
   'The electron has a very small mass compared with the proton, practically negligible in the total atomic mass.'),
  ('1789d6b2-9999-406d-b100-1b1a9c7ea9da', 'es',
   'En comparación con la del protón, la masa del electrón es:',
   array['Mucho menor, unas 1836 veces menor', 'Aproximadamente igual', 'Mucho mayor', 'El doble de la masa del protón'],
   'El electrón tiene una masa muy pequeña en relación con el protón, prácticamente despreciable en la masa atómica total.'),
  ('bbb10670-6bbf-49f8-b7d6-78f440f72ff3', 'en',
   'Valence electrons are mainly responsible for:',
   array['Determining the atom''s chemical behavior and bonds', 'Defining the atom''s total mass', 'Determining the atom''s number of neutrons', 'Setting the element''s atomic number'],
   'The electrons in the valence shell are the ones that take part in chemical bonds, determining the element''s reactivity.'),
  ('bbb10670-6bbf-49f8-b7d6-78f440f72ff3', 'es',
   'Los electrones de valencia son responsables, principalmente, de:',
   array['Determinar el comportamiento químico y los enlaces del átomo', 'Definir la masa total del átomo', 'Determinar el número de neutrones del átomo', 'Fijar el número atómico del elemento'],
   'Los electrones de la capa de valencia son los que participan en los enlaces químicos y determinan la reactividad del elemento.'),
  ('46f614f0-8983-4e81-b29b-194b33b4065c', 'en',
   'Isotopes are atoms of the same chemical element that have:',
   array['The same atomic number (Z) and different mass numbers (A)', 'The same mass number and different atomic numbers', 'Different atomic and mass numbers', 'Only the same number of valence electrons'],
   'Isotopes have the same number of protons but differ in the number of neutrons, which changes the mass number.'),
  ('46f614f0-8983-4e81-b29b-194b33b4065c', 'es',
   'Los isótopos son átomos de un mismo elemento químico que tienen:',
   array['El mismo número atómico (Z) y diferentes números másicos (A)', 'El mismo número másico y diferentes números atómicos', 'Diferentes números atómicos y másicos', 'Solo el mismo número de electrones de valencia'],
   'Los isótopos tienen el mismo número de protones, pero difieren en el número de neutrones, lo que altera el número másico.'),
  ('c98e0c8b-5060-4d70-b00b-1f48ebdf04c4', 'en',
   'Carbon-12 and carbon-14 are examples of:',
   array['Isotopes of the element carbon', 'Different chemical elements', 'Isobars', 'Isotones'],
   'Both have 6 protons (same element) but differ in the number of neutrons, so they are isotopes.'),
  ('c98e0c8b-5060-4d70-b00b-1f48ebdf04c4', 'es',
   'El carbono-12 y el carbono-14 son ejemplos de:',
   array['Isótopos del elemento carbono', 'Elementos químicos diferentes', 'Isóbaros', 'Isótonos'],
   'Ambos tienen 6 protones (mismo elemento), pero difieren en el número de neutrones, por lo que son isótopos.'),
  ('0ad4c56d-39ad-4a3a-88fa-107091153315', 'en',
   'Carbon-14, a radioactive isotope, is widely used for:',
   array['Dating organic materials (radiocarbon dating)', 'Large-scale nuclear power generation', 'Making special glass', 'Purifying drinking water'],
   'Radiocarbon dating uses the decay of carbon-14 to estimate the age of ancient organic materials.'),
  ('0ad4c56d-39ad-4a3a-88fa-107091153315', 'es',
   'El carbono-14, un isótopo radiactivo, se usa ampliamente para:',
   array['La datación de materiales orgánicos (datación por radiocarbono)', 'La producción de energía nuclear a gran escala', 'La fabricación de vidrios especiales', 'La purificación de agua potable'],
   'La datación por radiocarbono usa la desintegración del carbono-14 para estimar la edad de materiales orgánicos antiguos.'),
  ('bdd411a9-d46d-4411-9b10-28ce1659e22c', 'en',
   'Since isotopes of the same element have the same number of protons and electrons, their chemical properties are:',
   array['Very similar, since they depend mainly on the electronic structure', 'Completely different', 'Always opposite', 'Nonexistent, since isotopes do not react chemically'],
   'Since chemical behavior depends essentially on electrons, isotopes of the same element have very similar chemical properties.'),
  ('bdd411a9-d46d-4411-9b10-28ce1659e22c', 'es',
   'Como los isótopos de un mismo elemento tienen el mismo número de protones y electrones, sus propiedades químicas son:',
   array['Muy semejantes, ya que dependen principalmente de la estructura electrónica', 'Completamente diferentes', 'Siempre opuestas', 'Inexistentes, pues los isótopos no reaccionan químicamente'],
   'Como el comportamiento químico depende esencialmente de los electrones, los isótopos de un mismo elemento tienen propiedades químicas muy semejantes.'),
  ('2e8461eb-dba5-45ff-a1f6-afa98b8f3872', 'en',
   'An atom of uranium-238 (U-238) has atomic number 92. How many neutrons does this atom have?',
   array['146', '92', '238', '330'],
   'Number of neutrons = mass number - atomic number = 238 - 92 = 146.'),
  ('2e8461eb-dba5-45ff-a1f6-afa98b8f3872', 'es',
   'Un átomo de uranio-238 (U-238) tiene número atómico 92. ¿Cuántos neutrones tiene ese átomo?',
   array['146', '92', '238', '330'],
   'Número de neutrones = número másico - número atómico = 238 - 92 = 146.'),
  ('61c67cfa-fb60-4097-a438-89385ae58295', 'en',
   'Neutrons are subatomic particles characterized by:',
   array['Being in the atom''s nucleus and having no electric charge', 'Being in the electron cloud and having a negative charge', 'Having a positive electric charge', 'Not existing in neutral atoms'],
   'Neutrons, together with protons, form the atomic nucleus, but they have no electric charge.'),
  ('61c67cfa-fb60-4097-a438-89385ae58295', 'es',
   'Los neutrones son partículas subatómicas caracterizadas por:',
   array['Estar en el núcleo del átomo y no tener carga eléctrica', 'Estar en la corteza electrónica y tener carga negativa', 'Tener carga eléctrica positiva', 'No existir en los átomos neutros'],
   'Los neutrones, junto con los protones, forman el núcleo atómico, pero no tienen carga eléctrica.'),
  ('6c541d35-7423-48b4-b271-ca394d0c98f1', 'en',
   'The mass number (A) of an atom is calculated as:',
   array['The sum of the number of protons and neutrons', 'Only the number of protons', 'Only the number of neutrons', 'The sum of protons, neutrons and electrons'],
   'The mass number represents the total number of particles in the nucleus (protons + neutrons).'),
  ('6c541d35-7423-48b4-b271-ca394d0c98f1', 'es',
   'El número másico (A) de un átomo se calcula como:',
   array['La suma del número de protones y neutrones', 'Solo el número de protones', 'Solo el número de neutrones', 'La suma de protones, neutrones y electrones'],
   'El número másico representa el total de partículas del núcleo (protones + neutrones).'),
  ('1ab02890-736e-4d00-917b-09ee42b67a22', 'en',
   'A sodium (Na) atom has atomic number 11 and mass number 23. How many neutrons does this atom have?',
   array['12', '11', '23', '34'],
   'Number of neutrons = mass number - atomic number = 23 - 11 = 12.'),
  ('1ab02890-736e-4d00-917b-09ee42b67a22', 'es',
   'Un átomo de sodio (Na) tiene número atómico 11 y número másico 23. ¿Cuántos neutrones tiene ese átomo?',
   array['12', '11', '23', '34'],
   'Número de neutrones = número másico - número atómico = 23 - 11 = 12.'),
  ('0048f8df-12e1-42b4-bb9f-679d1d0505b4', 'en',
   'Neutrons contribute to the stability of the atomic nucleus mainly because they:',
   array['Help offset the electric repulsion between protons', 'Attract protons electrically', 'Repel the electrons in the electron cloud', 'Play no role in nuclear stability'],
   'Neutrons contribute to the strong nuclear force, helping hold the protons together despite their electric repulsion.'),
  ('0048f8df-12e1-42b4-bb9f-679d1d0505b4', 'es',
   'Los neutrones contribuyen a la estabilidad del núcleo atómico principalmente porque:',
   array['Ayudan a contrarrestar la repulsión eléctrica entre los protones', 'Atraen eléctricamente a los protones', 'Repelen a los electrones de la corteza', 'No tienen ningún papel en la estabilidad nuclear'],
   'Los neutrones contribuyen a la fuerza nuclear fuerte y ayudan a mantener unidos a los protones pese a la repulsión eléctrica.'),
  ('29784c1c-e643-48bb-9748-0bc5226273be', 'en',
   'Compared with that of a proton, the mass of a neutron is:',
   array['Approximately equal', 'Much smaller', 'Much larger', 'Zero'],
   'Protons and neutrons have very similar masses, both approximately 1 atomic mass unit.'),
  ('29784c1c-e643-48bb-9748-0bc5226273be', 'es',
   'En comparación con la de un protón, la masa de un neutrón es:',
   array['Aproximadamente igual', 'Mucho menor', 'Mucho mayor', 'Nula'],
   'Los protones y los neutrones tienen masas muy próximas, ambas de aproximadamente 1 unidad de masa atómica.'),
  ('47fba5c0-6e1a-4ca3-97dc-b4bd458ecd40', 'en',
   'Protons are subatomic particles located:',
   array['In the atom''s nucleus, with a positive electric charge', 'In the electron cloud, with a negative electric charge', 'In the atom''s nucleus, with no electric charge', 'Outside the atom, orbiting freely'],
   'Protons, which are positively charged, are located in the atomic nucleus, together with neutrons.'),
  ('47fba5c0-6e1a-4ca3-97dc-b4bd458ecd40', 'es',
   'Los protones son partículas subatómicas ubicadas:',
   array['En el núcleo del átomo, con carga eléctrica positiva', 'En la corteza electrónica, con carga eléctrica negativa', 'En el núcleo del átomo, sin carga eléctrica', 'Fuera del átomo, orbitando libremente'],
   'Los protones, de carga positiva, están en el núcleo atómico junto con los neutrones.'),
  ('78a3b839-67a7-4089-aaa6-ec5aed4fadec', 'en',
   'The atomic number (Z) of a chemical element corresponds to the number of:',
   array['Protons in the atom''s nucleus', 'Neutrons in the nucleus', 'Electrons in the outermost shell', 'Known isotopes of the element'],
   'The atomic number is defined by the number of protons, the feature that identifies each chemical element.'),
  ('78a3b839-67a7-4089-aaa6-ec5aed4fadec', 'es',
   'El número atómico (Z) de un elemento químico corresponde al número de:',
   array['Protones presentes en el núcleo del átomo', 'Neutrones presentes en el núcleo', 'Electrones en la última capa', 'Isótopos conocidos del elemento'],
   'El número atómico está definido por la cantidad de protones, característica que identifica a cada elemento químico.'),
  ('084dd6f8-325b-4134-bb7f-a8c6efe50517', 'en',
   'A neutral atom must necessarily have:',
   array['The same number of protons and electrons', 'The same number of protons and neutrons', 'More electrons than protons', 'More protons than electrons'],
   'For an atom to be electrically neutral, the number of protons must equal the number of electrons.'),
  ('084dd6f8-325b-4134-bb7f-a8c6efe50517', 'es',
   'Un átomo neutro debe tener necesariamente:',
   array['El mismo número de protones y electrones', 'El mismo número de protones y neutrones', 'Más electrones que protones', 'Más protones que electrones'],
   'Para que un átomo sea eléctricamente neutro, el número de protones debe igualar al de electrones.'),
  ('d4e302e3-9910-4a1b-b967-57174d3347e5', 'en',
   'The mass of a proton is approximately:',
   array['1 atomic mass unit (u)', '1/1836 of the mass of an electron', 'Equal to the mass of an electron', 'Negligible, like that of the electron'],
   'The proton has a mass of approximately 1 u, much greater than the mass of the electron.'),
  ('d4e302e3-9910-4a1b-b967-57174d3347e5', 'es',
   'La masa de un protón es aproximadamente:',
   array['1 unidad de masa atómica (u)', '1/1836 de la masa de un electrón', 'Igual a la masa de un electrón', 'Despreciable, similar a la del electrón'],
   'El protón tiene una masa aproximadamente igual a 1 u, mucho mayor que la masa del electrón.'),
  ('2e889e12-eccf-4459-918b-6411bf40aabe', 'en',
   'Compared with that of the electron, the electric charge of a proton is:',
   array['Of the same magnitude, but of opposite sign', 'Twice as large', 'Half as large', 'Zero, with no charge at all'],
   'Protons and electrons have charges of the same magnitude but of opposite signs.'),
  ('2e889e12-eccf-4459-918b-6411bf40aabe', 'es',
   'En relación con la del electrón, la carga eléctrica de un protón es:',
   array['De la misma intensidad, pero de signo opuesto', 'Dos veces mayor', 'La mitad de intensidad', 'Nula, sin ninguna carga'],
   'Los protones y los electrones tienen cargas de la misma intensidad, pero de signos opuestos.'),
  ('cb85d252-0fee-41bb-bffe-2c059bd9f538', 'en',
   'An atom that gains one or more electrons, becoming negatively charged, is called:',
   array['An anion', 'A cation', 'An isotope', 'An isobar'],
   'An anion forms by gaining electrons, resulting in a net negative electric charge.'),
  ('cb85d252-0fee-41bb-bffe-2c059bd9f538', 'es',
   'Un átomo que gana uno o más electrones y queda con carga negativa se llama:',
   array['Anión', 'Catión', 'Isótopo', 'Isóbaro'],
   'El anión se forma por la ganancia de electrones, lo que da como resultado una carga eléctrica neta negativa.'),
  ('4834aa85-0d83-41c4-b827-467c22a4cffe', 'en',
   'An atom that loses one or more electrons, becoming positively charged, is called:',
   array['A cation', 'An anion', 'An isotope', 'An isobar'],
   'A cation forms by losing electrons, resulting in a net positive electric charge.'),
  ('4834aa85-0d83-41c4-b827-467c22a4cffe', 'es',
   'Un átomo que pierde uno o más electrones y queda con carga positiva se llama:',
   array['Catión', 'Anión', 'Isótopo', 'Isóbaro'],
   'El catión se forma por la pérdida de electrones, lo que da como resultado una carga eléctrica neta positiva.'),
  ('12a1d6c0-4bd1-4546-9978-feda602c6058', 'en',
   'The Na⁺ (sodium) ion forms from the neutral sodium atom through:',
   array['Loss of one electron', 'Gain of one electron', 'Loss of one proton', 'Gain of one neutron'],
   'The symbol Na⁺ indicates a positive charge, the result of the neutral sodium atom losing one electron.'),
  ('12a1d6c0-4bd1-4546-9978-feda602c6058', 'es',
   'El ion Na⁺ (sodio) se forma a partir del átomo neutro de sodio mediante:',
   array['La pérdida de un electrón', 'La ganancia de un electrón', 'La pérdida de un protón', 'La ganancia de un neutrón'],
   'El símbolo Na⁺ indica carga positiva, resultado de la pérdida de un electrón por el átomo neutro de sodio.'),
  ('7cd8c3ad-b2cd-4b73-ab8a-a9056764f53a', 'en',
   'The Cl⁻ (chloride) ion forms from the neutral chlorine atom through:',
   array['Gain of one electron', 'Loss of one electron', 'Gain of one proton', 'Loss of one neutron'],
   'The symbol Cl⁻ indicates a negative charge, the result of the neutral chlorine atom gaining one electron.'),
  ('7cd8c3ad-b2cd-4b73-ab8a-a9056764f53a', 'es',
   'El ion Cl⁻ (cloruro) se forma a partir del átomo neutro de cloro mediante:',
   array['La ganancia de un electrón', 'La pérdida de un electrón', 'La ganancia de un protón', 'La pérdida de un neutrón'],
   'El símbolo Cl⁻ indica carga negativa, resultado de la ganancia de un electrón por el átomo neutro de cloro.'),
  ('3482264b-0bda-49d6-96fc-97895b38bb92', 'en',
   'In an ionic bond, such as the one formed between sodium and chlorine (NaCl), what happens is:',
   array['A transfer of electrons from one atom to another, forming a cation and an anion', 'An equal sharing of electrons between the atoms', 'A complete absence of interaction between the atoms', 'A transfer of protons between the atoms'],
   'In an ionic bond, one atom gives electrons to another, forming a cation and an anion that attract each other electrically.'),
  ('3482264b-0bda-49d6-96fc-97895b38bb92', 'es',
   'En un enlace iónico, como el que se forma entre el sodio y el cloro (NaCl), ocurre:',
   array['Una transferencia de electrones de un átomo a otro, que forma un catión y un anión', 'Una compartición equitativa de electrones entre los átomos', 'La ausencia total de interacción entre los átomos', 'Una transferencia de protones entre los átomos'],
   'En el enlace iónico, un átomo cede electrones a otro y se forman un catión y un anión que se atraen eléctricamente.'),
  ('2825b19c-8304-4d58-92e6-abf2d4268d5b', 'en',
   'Bohr''s atomic model introduced the central idea that electrons:',
   array['Occupy specific orbits, with well-defined (quantized) energy levels', 'Move completely randomly around the nucleus', 'Are located inside the nucleus itself', 'Have no relationship with the atom''s energy'],
   'Bohr proposed that electrons can only occupy certain allowed orbits, each associated with a specific energy level.'),
  ('2825b19c-8304-4d58-92e6-abf2d4268d5b', 'es',
   'El modelo atómico de Bohr introdujo la idea central de que los electrones:',
   array['Ocupan órbitas específicas, con niveles de energía bien definidos (cuantizados)', 'Se mueven de forma totalmente aleatoria alrededor del núcleo', 'Están dentro del propio núcleo', 'No tienen ninguna relación con la energía del átomo'],
   'Bohr propuso que los electrones solo pueden ocupar ciertas órbitas permitidas, cada una asociada a un nivel específico de energía.'),
  ('6795677c-0825-4b1a-a02c-ddcaa7ba961e', 'en',
   'According to Bohr''s model, an electron emits energy as light when it:',
   array['Jumps from a higher energy level to a lower one', 'Stays still in a single orbit', 'Jumps from a lower energy level to a higher one', 'Is completely removed from the atom'],
   'Light (a photon) is emitted when the electron returns from a higher energy level to a lower one.'),
  ('6795677c-0825-4b1a-a02c-ddcaa7ba961e', 'es',
   'Según el modelo de Bohr, un electrón emite energía en forma de luz cuando:',
   array['Salta de un nivel de energía más alto a uno más bajo', 'Permanece quieto en una única órbita', 'Salta de un nivel de energía más bajo a uno más alto', 'Es retirado por completo del átomo'],
   'La emisión de luz (fotón) ocurre cuando el electrón vuelve de un nivel de energía más alto a uno más bajo.'),
  ('07b95bb3-c2e2-440f-96b2-2b64bbeb2dfb', 'en',
   'According to Bohr, for an electron to jump from an inner orbit to an outer one, it must:',
   array['Absorb a specific amount of energy', 'Lose energy spontaneously', 'Stay unchanged, with no energy exchange', 'Collide with another electron in the same orbit'],
   'The transition to a higher energy level requires absorbing an exact (quantized) amount of energy.'),
  ('07b95bb3-c2e2-440f-96b2-2b64bbeb2dfb', 'es',
   'Según Bohr, para que un electrón salte de una órbita más interna a una más externa, debe:',
   array['Absorber una cantidad específica de energía', 'Perder energía espontáneamente', 'Permanecer igual, sin ningún intercambio de energía', 'Chocar con otro electrón de la misma órbita'],
   'La transición a un nivel de mayor energía exige la absorción de una cantidad exacta (cuantizada) de energía.'),
  ('5ba44844-dd89-48e0-b5ed-dfcaa38e914d', 'en',
   'Bohr''s model was developed especially to successfully explain the emission spectrum of the atom of:',
   array['Hydrogen', 'Gold', 'Carbon', 'Uranium'],
   'Bohr''s model was very successful in explaining the line spectrum of the hydrogen atom, the simplest of all.'),
  ('5ba44844-dd89-48e0-b5ed-dfcaa38e914d', 'es',
   'El modelo de Bohr se desarrolló especialmente para explicar con éxito el espectro de emisión del átomo de:',
   array['Hidrógeno', 'Oro', 'Carbono', 'Uranio'],
   'El modelo de Bohr tuvo gran éxito al explicar el espectro de líneas del átomo de hidrógeno, el más simple de todos.'),
  ('2196e3d5-df43-4d03-a81d-ff74f3fc00a9', 'en',
   'Bohr''s model represents an important transition in the history of atomic physics because it incorporated, for the first time, concepts from:',
   array['Quantum physics, with the idea of energy quantization', 'Classical Newtonian physics, exclusively', 'The theory of general relativity', 'Classical thermodynamics'],
   'Bohr was a pioneer in applying the idea of energy quantization to atomic structure.'),
  ('2196e3d5-df43-4d03-a81d-ff74f3fc00a9', 'es',
   'El modelo de Bohr representa una transición importante en la historia de la física atómica por incorporar, por primera vez, conceptos de la:',
   array['Física cuántica, con la idea de la cuantización de la energía', 'Física clásica newtoniana, exclusivamente', 'Teoría de la relatividad general', 'Termodinámica clásica'],
   'Bohr fue pionero al aplicar la idea de la cuantización de la energía a la estructura atómica.'),
  ('0f74f208-8d73-4d9f-83de-25981fd16246', 'en',
   'Dalton''s atomic model, proposed in the early 19th century, conceived of the atom as:',
   array['A solid, indivisible and indestructible sphere', 'A positively charged sphere with scattered electrons', 'A small, dense nucleus surrounded by an electron cloud', 'A system of quantized orbits for the electrons'],
   'Dalton proposed the atom as a solid, indivisible sphere, like a "billiard ball".'),
  ('0f74f208-8d73-4d9f-83de-25981fd16246', 'es',
   'El modelo atómico de Dalton, propuesto a principios del siglo XIX, concebía el átomo como:',
   array['Una esfera maciza, indivisible e indestructible', 'Una esfera con carga positiva que contiene electrones dispersos', 'Un núcleo pequeño y denso rodeado por una corteza electrónica', 'Un sistema de órbitas cuantizadas para los electrones'],
   'Dalton propuso el átomo como una esfera maciza e indivisible, semejante a una "bola de billar".'),
  ('4b0c286d-a5f4-40a9-a7f2-089f72b72afd', 'en',
   'One of the postulates of Dalton''s model stated that:',
   array['Atoms of the same chemical element are identical to one another', 'Atoms can be divided into smaller particles', 'Atoms of different elements always have the same mass', 'Matter is not made up of atoms'],
   'Dalton postulated that all atoms of the same element were identical in mass and properties.'),
  ('4b0c286d-a5f4-40a9-a7f2-089f72b72afd', 'es',
   'Uno de los postulados del modelo de Dalton afirmaba que:',
   array['Los átomos de un mismo elemento químico son idénticos entre sí', 'Los átomos pueden dividirse en partículas más pequeñas', 'Los átomos de elementos diferentes tienen siempre la misma masa', 'La materia no está compuesta por átomos'],
   'Dalton postulaba que todos los átomos de un mismo elemento eran idénticos en masa y propiedades.'),
  ('58c0634d-6628-43fa-84e8-26a684ab6d2d', 'en',
   'Dalton''s atomic model was later superseded mainly by the discovery of:',
   array['Subatomic particles, such as the electron', 'New chemical elements', 'The periodic table', 'Organic chemical reactions'],
   'Thomson''s discovery of the electron showed that the atom was not indivisible, as Dalton had proposed.'),
  ('58c0634d-6628-43fa-84e8-26a684ab6d2d', 'es',
   'El modelo atómico de Dalton fue superado posteriormente, principalmente, por el descubrimiento de:',
   array['Partículas subatómicas, como el electrón', 'Nuevos elementos químicos', 'La tabla periódica', 'Reacciones químicas orgánicas'],
   'El descubrimiento del electrón, por Thomson, mostró que el átomo no era indivisible como proponía Dalton.'),
  ('9572aaae-ef63-4987-a173-d4ab09b57786', 'en',
   'According to Dalton''s model, chemical reactions consisted of:',
   array['Rearrangements of atoms, without creating or destroying them', 'The complete destruction of the atoms involved', 'The spontaneous creation of new atoms', 'Phenomena unrelated to atoms'],
   'Dalton explained chemical reactions as simple reorganizations of existing atoms.'),
  ('9572aaae-ef63-4987-a173-d4ab09b57786', 'es',
   'Según el modelo de Dalton, las reacciones químicas consistían en:',
   array['Reordenamientos de átomos, sin crearlos ni destruirlos', 'La destrucción completa de los átomos involucrados', 'La creación espontánea de nuevos átomos', 'Fenómenos sin ninguna relación con los átomos'],
   'Dalton explicaba las reacciones químicas como simples reorganizaciones de átomos preexistentes.'),
  ('3bff2191-0536-4a1a-b954-cd69789da262', 'en',
   'Dalton''s atomic model is often represented, in simplified form, by the image of:',
   array['A billiard ball', 'A plum pudding', 'A planetary system', 'A probability cloud'],
   'The "billiard ball" analogy illustrates Dalton''s idea of a solid, indivisible sphere.'),
  ('3bff2191-0536-4a1a-b954-cd69789da262', 'es',
   'El modelo atómico de Dalton suele representarse, de forma simplificada, con la imagen de:',
   array['Una bola de billar', 'Un pudín con pasas', 'Un sistema planetario', 'Una nube de probabilidad'],
   'La analogía con la "bola de billar" ilustra la idea de esfera maciza e indivisible propuesta por Dalton.'),
  ('b215de02-b76e-45ef-be2c-dd5b78168b6f', 'en',
   'Rutherford''s atomic model, the result of his famous gold foil experiment, proposed the existence of:',
   array['A small, dense, positive nucleus surrounded by an electron cloud with a lot of empty space', 'A completely solid atom, with no empty space', 'Electrons distributed evenly throughout the atomic sphere', 'Electron orbits with fixed energy levels'],
   'Rutherford concluded that the atom has a small, dense nucleus with a lot of empty space around it.'),
  ('b215de02-b76e-45ef-be2c-dd5b78168b6f', 'es',
   'El modelo atómico de Rutherford, resultado de su famoso experimento con una lámina de oro, propuso la existencia de:',
   array['Un núcleo pequeño, denso y positivo, rodeado por una corteza electrónica con gran espacio vacío', 'Un átomo totalmente macizo, sin espacios vacíos', 'Electrones distribuidos uniformemente por toda la esfera atómica', 'Órbitas electrónicas con niveles de energía fijos'],
   'Rutherford concluyó que el átomo tiene un núcleo pequeño y denso, con un gran espacio vacío a su alrededor.'),
  ('39f31496-f05a-49ad-8370-47cce094016e', 'en',
   'In Rutherford''s experiment, most of the alpha particles fired at the gold foil:',
   array['Passed through the foil without significant deflection', 'Were completely reflected', 'Got stuck inside the foil', 'Turned into electrons'],
   'The vast majority of particles passed through the foil without deflection, showing that the atom is mostly empty space.'),
  ('39f31496-f05a-49ad-8370-47cce094016e', 'es',
   'En el experimento de Rutherford, la mayoría de las partículas alfa lanzadas contra la lámina de oro:',
   array['Atravesó la lámina sin sufrir desviaciones significativas', 'Fue reflejada por completo', 'Quedó atrapada dentro de la lámina', 'Se transformó en electrones'],
   'La gran mayoría de las partículas atravesó la lámina sin desviarse, lo que evidenció que el átomo está compuesto mayoritariamente por espacio vacío.'),
  ('54752cee-018d-4e26-b62a-cab24c3366a2', 'en',
   'The deflection observed in a few alpha particles in Rutherford''s experiment indicated:',
   array['The existence of a small, dense, positively charged nucleus', 'The complete absence of charge in the atom', 'That the atom was completely solid', 'That electrons had a positive charge'],
   'The deflection of some particles revealed a concentrated region of positive charge: the nucleus.'),
  ('54752cee-018d-4e26-b62a-cab24c3366a2', 'es',
   'La desviación observada en algunas partículas alfa en el experimento de Rutherford indicaba:',
   array['La existencia de un núcleo pequeño, denso y con carga positiva', 'La ausencia total de carga en el átomo', 'Que el átomo era totalmente macizo', 'Que los electrones tenían carga positiva'],
   'La desviación de algunas partículas reveló la presencia de una región concentrada de carga positiva: el núcleo.'),
  ('e60a4872-1fa5-4208-a869-c72e8395ad1a', 'en',
   'Rutherford''s model is often compared to a system that is:',
   array['Planetary, with electrons orbiting the nucleus', 'Like a plum pudding', 'A solid sphere with no internal structure', 'Made of standing waves'],
   'The comparison with the solar system is the classic analogy for Rutherford''s model.'),
  ('e60a4872-1fa5-4208-a869-c72e8395ad1a', 'es',
   'El modelo de Rutherford suele compararse con un sistema:',
   array['Planetario, con los electrones orbitando el núcleo', 'De pudín de pasas', 'De esfera maciza sin estructura interna', 'De ondas estacionarias'],
   'La comparación con el sistema solar es la analogía clásica del modelo de Rutherford.'),
  ('0944dac9-4bb7-4903-829f-e016ab9d0420', 'en',
   'A limitation of Rutherford''s model, later resolved by Bohr, was that it:',
   array['Did not explain why the electrons did not collapse into the nucleus', 'Did not consider the existence of the atomic nucleus', 'Did not recognize the existence of protons', 'Did not allow for empty space in the atom'],
   'According to classical physics, orbiting electrons should lose energy and collapse into the nucleus, a problem solved by Bohr''s model.'),
  ('0944dac9-4bb7-4903-829f-e016ab9d0420', 'es',
   'Una limitación del modelo de Rutherford, resuelta después por Bohr, era:',
   array['No explicar por qué los electrones no colapsaban sobre el núcleo', 'No considerar la existencia del núcleo atómico', 'No reconocer la existencia de los protones', 'No admitir espacios vacíos en el átomo'],
   'Según la física clásica, los electrones en órbita deberían perder energía y colapsar en el núcleo, problema que resolvió el modelo de Bohr.'),
  ('13793a36-244e-49ba-abab-94fd5b78ac8d', 'en',
   'Thomson''s atomic model, proposed after the discovery of the electron, is popularly known as the:',
   array['"Plum pudding" model', 'Planetary model', 'Billiard ball model', 'Quantum model'],
   'Thomson imagined the atom as a sphere of positive charge with electrons (the "plums") scattered inside it.'),
  ('13793a36-244e-49ba-abab-94fd5b78ac8d', 'es',
   'El modelo atómico de Thomson, propuesto tras el descubrimiento del electrón, se conoce popularmente como:',
   array['Modelo del "pudín de pasas"', 'Modelo planetario', 'Modelo de la bola de billar', 'Modelo cuántico'],
   'Thomson imaginaba el átomo como una esfera de carga positiva con electrones (las "pasas") dispersos en su interior.'),
  ('c0f33425-e104-4c08-8f7e-6b5beabcb770', 'en',
   'Thomson''s model was an advance over Dalton''s because it recognized that the atom:',
   array['Is divisible and has subatomic particles with electric charge', 'Is completely solid and indivisible', 'Has no electric charge at all', 'Is made up exclusively of protons'],
   'With the discovery of the electron, Thomson showed that the atom has an internal structure and charged particles.'),
  ('c0f33425-e104-4c08-8f7e-6b5beabcb770', 'es',
   'El modelo de Thomson representó un avance respecto al de Dalton por reconocer que el átomo:',
   array['Es divisible y tiene partículas subatómicas con carga eléctrica', 'Es totalmente macizo e indivisible', 'No tiene ninguna carga eléctrica', 'Está formado exclusivamente por protones'],
   'Con el descubrimiento del electrón, Thomson demostró que el átomo tiene estructura interna y partículas con carga.'),
  ('68e1a310-c4a0-45c2-95e3-26b7cb0bf2a9', 'en',
   'In Thomson''s model, the atom''s positive charge was distributed:',
   array['Diffusely throughout the atomic sphere', 'Concentrated in a small, dense nucleus', 'Only on the outer surface of the atom', 'Nowhere, since the atom would be completely neutral at every point'],
   'Unlike Rutherford''s later model, Thomson imagined the positive charge spread throughout the atomic sphere.'),
  ('68e1a310-c4a0-45c2-95e3-26b7cb0bf2a9', 'es',
   'En el modelo de Thomson, la carga positiva del átomo estaría distribuida:',
   array['De forma difusa por toda la esfera atómica', 'Concentrada en un núcleo pequeño y denso', 'Solo en la superficie externa del átomo', 'En ninguna parte, pues el átomo sería totalmente neutro en cualquier punto'],
   'A diferencia del modelo posterior de Rutherford, Thomson imaginaba la carga positiva repartida por toda la esfera atómica.'),
  ('5e642167-2e98-460d-903c-4a50d2028877', 'en',
   'Thomson''s model was later refuted by the experiment of:',
   array['Rutherford, with the scattering of alpha particles', 'Dalton, with the law of definite proportions', 'Bohr, with energy levels', 'Mendeleev, with the periodic table'],
   'Rutherford''s experiment showed that the positive charge was concentrated in a nucleus, refuting Thomson''s model.'),
  ('5e642167-2e98-460d-903c-4a50d2028877', 'es',
   'El modelo de Thomson fue refutado posteriormente por el experimento de:',
   array['Rutherford, con la dispersión de partículas alfa', 'Dalton, con la ley de las proporciones definidas', 'Bohr, con los niveles de energía', 'Mendeléyev, con la tabla periódica'],
   'El experimento de Rutherford mostró que la carga positiva estaba concentrada en un núcleo, lo que refutó el modelo de Thomson.'),
  ('55034579-7505-41ae-a949-d5ab42b2844c', 'en',
   'The main contribution of Thomson''s model to the development of atomic theory was:',
   array['Recognizing the electron as a subatomic particle', 'Proposing the existence of the atomic nucleus', 'Establishing quantized energy levels', 'Determining the number of neutrons in the elements'],
   'Thomson''s main contribution was incorporating the electron, which he discovered, into the atomic model.'),
  ('55034579-7505-41ae-a949-d5ab42b2844c', 'es',
   'La principal contribución del modelo de Thomson a la evolución de la teoría atómica fue:',
   array['Reconocer la existencia del electrón como partícula subatómica', 'Proponer la existencia del núcleo atómico', 'Establecer los niveles cuantizados de energía', 'Determinar el número de neutrones de los elementos'],
   'La principal contribución de Thomson fue incorporar al modelo atómico el electrón, que él mismo descubrió.'),
  ('3930d070-0e3d-42bc-b201-24dc21a4d209', 'en',
   'In the periodic table, families (or groups) correspond to:',
   array['The vertical columns, which bring together elements with similar chemical properties', 'The horizontal rows', 'Only the transition elements', 'A division based exclusively on atomic mass'],
   'Elements in the same family (column) share similar chemical characteristics.'),
  ('3930d070-0e3d-42bc-b201-24dc21a4d209', 'es',
   'En la tabla periódica, las familias (o grupos) corresponden:',
   array['A las columnas verticales, que reúnen elementos con propiedades químicas semejantes', 'A las filas horizontales', 'Solo a los elementos de transición', 'A una división basada exclusivamente en la masa atómica'],
   'Los elementos de una misma familia (columna) comparten características químicas semejantes.'),
  ('098610df-9e9c-4bea-98fa-85be3a3c9eb3', 'en',
   'Elements of the same family usually share the same number of:',
   array['Electrons in the valence shell', 'Total electron shells', 'Neutrons in the nucleus', 'Known isotopes'],
   'The number of valence electrons, similar among the elements of a family, is mainly responsible for their similar properties.'),
  ('098610df-9e9c-4bea-98fa-85be3a3c9eb3', 'es',
   'Los elementos de una misma familia comparten, generalmente, el mismo número de:',
   array['Electrones en la capa de valencia', 'Capas electrónicas totales', 'Neutrones en el núcleo', 'Isótopos conocidos'],
   'El número de electrones de valencia, semejante entre los elementos de una familia, es el principal responsable de la semejanza de sus propiedades.'),
  ('b8f428d1-5dd7-4b32-991a-6dfd9dbba26a', 'en',
   'Family 1 (or IA) of the periodic table, made up of the alkali metals, is characterized by having:',
   array['One electron in the valence shell', 'Seven electrons in the valence shell', 'Eight electrons in the valence shell', 'No electrons in the valence shell'],
   'Alkali metals have only 1 valence electron, which makes them highly reactive.'),
  ('b8f428d1-5dd7-4b32-991a-6dfd9dbba26a', 'es',
   'La familia 1 (o IA) de la tabla periódica, formada por los metales alcalinos, se caracteriza por tener:',
   array['Un electrón en la capa de valencia', 'Siete electrones en la capa de valencia', 'Ocho electrones en la capa de valencia', 'Ningún electrón en la capa de valencia'],
   'Los metales alcalinos tienen solo 1 electrón de valencia, lo que los hace muy reactivos.'),
  ('c3545cd1-8f44-4116-86db-c730ee49faa5', 'en',
   'Family 17 (or VIIA) of the periodic table, made up of the halogens, is characterized by having:',
   array['Seven electrons in the valence shell', 'One electron in the valence shell', 'Eight electrons in the valence shell', 'Two electrons in the valence shell'],
   'Halogens have 7 valence electrons, only 1 electron short of completing the octet.'),
  ('c3545cd1-8f44-4116-86db-c730ee49faa5', 'es',
   'La familia 17 (o VIIA) de la tabla periódica, formada por los halógenos, se caracteriza por tener:',
   array['Siete electrones en la capa de valencia', 'Un electrón en la capa de valencia', 'Ocho electrones en la capa de valencia', 'Dos electrones en la capa de valencia'],
   'Los halógenos tienen 7 electrones de valencia y les falta solo 1 electrón para completar el octeto.'),
  ('85ee0427-1049-487e-b918-13a6ac52d4e3', 'en',
   'Elements of the same family usually have similar chemical properties because:',
   array['They have similar valence electron configurations', 'They always have the same number of protons', 'They are always in the same period', 'They always have the same atomic mass'],
   'The similarity in the electron configuration of the valence shell determines the similar chemical behavior within a family.'),
  ('85ee0427-1049-487e-b918-13a6ac52d4e3', 'es',
   'Los elementos de una misma familia suelen tener propiedades químicas semejantes porque:',
   array['Tienen configuraciones electrónicas de valencia semejantes', 'Tienen siempre el mismo número de protones', 'Están siempre en el mismo período', 'Tienen siempre la misma masa atómica'],
   'La semejanza en la configuración electrónica de la capa de valencia determina el comportamiento químico semejante dentro de una familia.'),
  ('9fd7591b-05a3-44cd-a895-e62557d1b81c', 'en',
   'The noble gases, in the last family (18 or VIIIA) of the periodic table, are mainly characterized by:',
   array['Having a complete valence shell, which makes them not very reactive', 'Being the most reactive elements in the periodic table', 'Having only 1 valence electron', 'Not existing naturally, all being synthetic'],
   'With a complete valence shell, the noble gases are very chemically stable and have low reactivity.'),
  ('9fd7591b-05a3-44cd-a895-e62557d1b81c', 'es',
   'Los gases nobles, ubicados en la última familia (18 o VIIIA) de la tabla periódica, se caracterizan principalmente por:',
   array['Tener la capa de valencia completa, por lo que son poco reactivos', 'Ser los elementos más reactivos de la tabla periódica', 'Tener solo 1 electrón de valencia', 'No existir en la naturaleza, siendo todos sintéticos'],
   'Con la capa de valencia completa, los gases nobles tienen gran estabilidad química y baja reactividad.'),
  ('c80a3852-3335-4a4b-84d0-7c3b7725d005', 'en',
   'Helium, a noble gas widely used to fill balloons, is characterized by:',
   array['Being lighter than air and chemically not very reactive', 'Being highly reactive and flammable', 'Being denser than air', 'Reacting easily with water'],
   'Helium is light, inert and nonflammable, which makes it safe to use in balloons.'),
  ('c80a3852-3335-4a4b-84d0-7c3b7725d005', 'es',
   'El helio, un gas noble muy usado para inflar globos, se caracteriza por:',
   array['Ser más liviano que el aire y químicamente poco reactivo', 'Ser muy reactivo e inflamable', 'Ser más denso que el aire', 'Reaccionar fácilmente con el agua'],
   'El helio es liviano, inerte y no inflamable, características que lo hacen seguro para usar en globos.'),
  ('c3699579-0a3a-4c34-b242-fcbc603bfc10', 'en',
   'Neon, another noble gas, is well known for its use in:',
   array['Lighting illuminated signs (neon lights)', 'Nuclear power generation', 'Making batteries', 'Purifying water'],
   'When subjected to electric discharges in tubes, neon emits a characteristic reddish light, used in illuminated signs.'),
  ('c3699579-0a3a-4c34-b242-fcbc603bfc10', 'es',
   'El neón, otro gas noble, es bastante conocido por su aplicación en:',
   array['La iluminación de letreros luminosos (luces de neón)', 'La producción de energía nuclear', 'La fabricación de baterías', 'La purificación de agua'],
   'Al someterse a descargas eléctricas en tubos, el neón emite una luz rojiza característica, usada en letreros luminosos.'),
  ('c638ab54-1c7d-4600-8c0f-cb0982e2909c', 'en',
   'Unlike most elements, noble gases rarely form chemical compounds because:',
   array['They already have a stable electron configuration, with a complete valence shell', 'They have no valence electrons', 'They are always found in the liquid state', 'They only react with alkali metals'],
   'Electronic stability drastically reduces the tendency of noble gases to form chemical bonds.'),
  ('c638ab54-1c7d-4600-8c0f-cb0982e2909c', 'es',
   'A diferencia de la mayoría de los elementos, los gases nobles difícilmente forman compuestos químicos porque:',
   array['Ya tienen una configuración electrónica estable, con la capa de valencia completa', 'No tienen electrones de valencia', 'Se encuentran siempre en estado líquido', 'Solo reaccionan con los metales alcalinos'],
   'La estabilidad electrónica reduce drásticamente la tendencia de los gases nobles a formar enlaces químicos.'),
  ('b6617764-a905-4ab8-8e41-fb1d7d192255', 'en',
   'Argon, the most abundant noble gas in Earth''s atmosphere, is used, for example, in:',
   array['Incandescent light bulbs, as a gas that protects the filament', 'Nuclear reactors as the main fuel', 'The production of agricultural fertilizers', 'The manufacture of explosives'],
   'Being inert, argon is used inside incandescent bulbs to prevent the hot filament from oxidizing.'),
  ('b6617764-a905-4ab8-8e41-fb1d7d192255', 'es',
   'El argón, el gas noble más abundante en la atmósfera terrestre, se usa, por ejemplo, en:',
   array['Bombillas incandescentes, como gas que protege el filamento', 'Reactores nucleares como combustible principal', 'La producción de fertilizantes agrícolas', 'La fabricación de explosivos'],
   'Al ser inerte, el argón se usa dentro de las bombillas incandescentes para evitar la oxidación del filamento caliente.'),
  ('23ebfac1-612a-4320-8cc5-3da8e4877c2a', 'en',
   'The halogens, in family 17 (VIIA) of the periodic table, are characterized by:',
   array['Having 7 electrons in the valence shell, which makes them highly reactive', 'Having only 1 electron in the valence shell', 'Being extremely chemically inert', 'Forming only cations'],
   'With 7 valence electrons, halogens tend to gain 1 electron to complete the octet, which makes them very reactive.'),
  ('23ebfac1-612a-4320-8cc5-3da8e4877c2a', 'es',
   'Los halógenos, ubicados en la familia 17 (VIIA) de la tabla periódica, se caracterizan por:',
   array['Tener 7 electrones en la capa de valencia, por lo que son muy reactivos', 'Tener solo 1 electrón en la capa de valencia', 'Ser químicamente muy inertes', 'Formar exclusivamente cationes'],
   'Con 7 electrones de valencia, los halógenos tienden a ganar 1 electrón para completar el octeto, lo que los hace muy reactivos.'),
  ('073e015c-d0a3-47c5-b5e1-4ef8c1b58f44', 'en',
   'When they gain an electron, halogens form ions with a charge of:',
   array['-1 (monovalent anions)', '+1 (monovalent cations)', '-2', 'Neutral, no charge'],
   'Gaining 1 electron results in an anion with a charge of -1, such as Cl⁻ (chloride) and F⁻ (fluoride).'),
  ('073e015c-d0a3-47c5-b5e1-4ef8c1b58f44', 'es',
   'Al ganar un electrón, los halógenos forman iones con carga:',
   array['-1 (aniones monovalentes)', '+1 (cationes monovalentes)', '-2', 'Neutra, sin carga'],
   'La ganancia de 1 electrón da como resultado un anión de carga -1, como Cl⁻ (cloruro) y F⁻ (fluoruro).'),
  ('7321f158-d24b-4e54-92ca-49919f4782b4', 'en',
   'Chlorine, a widely used halogen, is commonly employed in:',
   array['Treating and disinfecting drinking water', 'Making inflatable balloons', 'Producing synthetic noble gases', 'Lighting illuminated signs'],
   'Chlorine is widely used as a disinfectant, above all in treating drinking water and in swimming pools.'),
  ('7321f158-d24b-4e54-92ca-49919f4782b4', 'es',
   'El cloro, un halógeno muy utilizado, se emplea comúnmente en:',
   array['El tratamiento y la desinfección del agua potable', 'La fabricación de globos inflables', 'La producción de gases nobles sintéticos', 'La iluminación de letreros luminosos'],
   'El cloro se usa ampliamente como desinfectante, sobre todo en el tratamiento del agua para consumo y en piscinas.'),
  ('857ebce5-e6f1-48b5-8cf7-2c992b27c7e3', 'en',
   'Fluorine, the most reactive halogen in the whole periodic table, is commonly added to oral hygiene products because it:',
   array['Helps prevent tooth decay', 'Is a food preservative', 'Whitens teeth instantly', 'Completely replaces the calcium in teeth'],
   'Fluorine strengthens tooth enamel and is widely used in toothpaste to prevent cavities.'),
  ('857ebce5-e6f1-48b5-8cf7-2c992b27c7e3', 'es',
   'El flúor, el halógeno más reactivo de toda la tabla periódica, se añade comúnmente a los productos de higiene bucal porque:',
   array['Ayuda a prevenir las caries dentales', 'Es un conservante alimentario', 'Blanquea los dientes al instante', 'Sustituye por completo el calcio de los dientes'],
   'El flúor fortalece el esmalte dental y se usa ampliamente en las pastas dentales para prevenir caries.'),
  ('01de9d03-fbb3-489f-9987-84e8e8e18e84', 'en',
   'Halogens can be found in nature in all three physical states, such as fluorine (gas), bromine (liquid) and iodine (solid), which illustrates:',
   array['The wide variation in physical properties within the same chemical family', 'That all the elements in a family always have the same physical state', 'That halogens cannot exist in the solid state', 'That the halogen family is made up of noble gases'],
   'Although they share similar chemical properties, halogens have different physical states at room temperature.'),
  ('01de9d03-fbb3-489f-9987-84e8e8e18e84', 'es',
   'Los halógenos pueden encontrarse en la naturaleza en los tres estados físicos, como el flúor (gas), el bromo (líquido) y el yodo (sólido), lo que ilustra:',
   array['La gran variación de propiedades físicas dentro de una misma familia química', 'Que todos los elementos de una familia tienen siempre el mismo estado físico', 'Que los halógenos no pueden existir en estado sólido', 'Que la familia de los halógenos está compuesta por gases nobles'],
   'Aunque comparten propiedades químicas semejantes, los halógenos tienen estados físicos distintos a temperatura ambiente.'),
  ('4c98e406-f237-4df0-8817-64d0596d6723', 'en',
   'The alkali metals, in family 1 (IA) of the periodic table, are characterized by:',
   array['Having only 1 electron in the valence shell, which makes them very reactive', 'Having 7 electrons in the valence shell', 'Being extremely chemically inert', 'Not reacting with water under any conditions'],
   'With only 1 valence electron, alkali metals tend to lose it easily, which makes them highly reactive.'),
  ('4c98e406-f237-4df0-8817-64d0596d6723', 'es',
   'Los metales alcalinos, ubicados en la familia 1 (IA) de la tabla periódica, se caracterizan por:',
   array['Tener solo 1 electrón en la capa de valencia, por lo que son muy reactivos', 'Tener 7 electrones en la capa de valencia', 'Ser químicamente muy inertes', 'No reaccionar con el agua en ninguna condición'],
   'Con solo 1 electrón de valencia, los metales alcalinos tienden a perderlo con facilidad, lo que los hace muy reactivos.'),
  ('9e276ac1-3c79-4724-acbe-26b02ba7ca07', 'en',
   'Alkali metals, such as sodium and potassium, react vigorously on contact with:',
   array['Water', 'Mineral oil', 'Nitrogen gas', 'Noble gases'],
   'Alkali metals react violently with water, releasing hydrogen gas and heat.'),
  ('9e276ac1-3c79-4724-acbe-26b02ba7ca07', 'es',
   'Los metales alcalinos, como el sodio y el potasio, reaccionan vigorosamente al entrar en contacto con:',
   array['Agua', 'Aceite mineral', 'Nitrógeno gaseoso', 'Gases nobles'],
   'Los metales alcalinos reaccionan violentamente con el agua, liberando gas hidrógeno y calor.'),
  ('327f1fac-5da4-45a3-8d6d-37f9977deb0e', 'en',
   'Because they are highly reactive, alkali metals are usually stored:',
   array['Immersed in mineral oil, to avoid contact with air and moisture', 'Freely exposed to air', 'In containers of water', 'Under high pressure of pure oxygen'],
   'Storing them in mineral oil prevents these metals from reacting with oxygen and moisture in the air.'),
  ('327f1fac-5da4-45a3-8d6d-37f9977deb0e', 'es',
   'Por ser muy reactivos, los metales alcalinos se almacenan generalmente:',
   array['Sumergidos en aceite mineral, para evitar el contacto con el aire y la humedad', 'Expuestos libremente al aire', 'En recipientes con agua', 'Bajo alta presión de oxígeno puro'],
   'Almacenarlos en aceite mineral evita que estos metales reaccionen con el oxígeno y la humedad del aire.'),
  ('cadaa83c-d9fb-40e0-9179-6fe0fb565985', 'en',
   'When they lose their single valence electron, alkali metals form ions with a charge of:',
   array['+1 (monovalent cations)', '-1 (monovalent anions)', '+2', 'Neutral, no charge'],
   'Losing the single valence electron results in a cation with a charge of +1, such as Na⁺ and K⁺.'),
  ('cadaa83c-d9fb-40e0-9179-6fe0fb565985', 'es',
   'Al perder su único electrón de valencia, los metales alcalinos forman iones con carga:',
   array['+1 (cationes monovalentes)', '-1 (aniones monovalentes)', '+2', 'Neutra, sin carga'],
   'La pérdida del único electrón de valencia da como resultado un catión de carga +1, como Na⁺ y K⁺.'),
  ('6fc036e7-26f4-43f7-b244-177d0e70af82', 'en',
   'Sodium (Na) and potassium (K) are examples of:',
   array['Alkali metals', 'Noble gases', 'Halogens', 'Metalloids'],
   'Sodium and potassium belong to family 1 (IA) of the periodic table and are classified as alkali metals.'),
  ('6fc036e7-26f4-43f7-b244-177d0e70af82', 'es',
   'El sodio (Na) y el potasio (K) son ejemplos de:',
   array['Metales alcalinos', 'Gases nobles', 'Halógenos', 'Semimetales'],
   'El sodio y el potasio pertenecen a la familia 1 (IA) de la tabla periódica y se clasifican como metales alcalinos.'),
  ('f3adf324-8386-4a68-8eed-d8a32f7e71e6', 'en',
   'In the periodic table, most chemical elements are classified as:',
   array['Metals', 'Nonmetals', 'Metalloids', 'Noble gases'],
   'Metals make up most of the known elements, occupying the largest area of the periodic table.'),
  ('f3adf324-8386-4a68-8eed-d8a32f7e71e6', 'es',
   'En la tabla periódica, la mayoría de los elementos químicos se clasifica como:',
   array['Metales', 'No metales', 'Semimetales', 'Gases nobles'],
   'Los metales representan la mayor parte de los elementos conocidos y ocupan la mayor área de la tabla periódica.'),
  ('f5c93a05-a4bc-47b1-b834-5c5335b206ef', 'en',
   'A typical characteristic of metals, in contrast with nonmetals, is:',
   array['Good electrical and thermal conductivity', 'Low electrical conductivity', 'A tendency to gain electrons in bonds', 'Being gaseous at room temperature, in general'],
   'Metals are, in general, good conductors of electricity and heat, as well as ductile and malleable.'),
  ('f5c93a05-a4bc-47b1-b834-5c5335b206ef', 'es',
   'Una característica típica de los metales, en contraste con los no metales, es:',
   array['Buena conductividad eléctrica y térmica', 'Baja conductividad eléctrica', 'La tendencia a ganar electrones en los enlaces', 'El estado gaseoso a temperatura ambiente, en general'],
   'Los metales son, en general, buenos conductores de la electricidad y el calor, además de dúctiles y maleables.'),
  ('c7573812-cd0e-4ae5-83bb-750fa2d1805f', 'en',
   'Metalloids (or semimetals), such as silicon and germanium, have properties that are:',
   array['Intermediate between metals and nonmetals', 'Identical to those of metals in every respect', 'Identical to those of nonmetals in every respect', 'Exclusive to noble gases'],
   'Metalloids combine characteristics of metals and nonmetals and are widely used as semiconductors.'),
  ('c7573812-cd0e-4ae5-83bb-750fa2d1805f', 'es',
   'Los semimetales (o metaloides), como el silicio y el germanio, tienen propiedades:',
   array['Intermedias entre las de los metales y los no metales', 'Idénticas a las de los metales en todos los aspectos', 'Idénticas a las de los no metales en todos los aspectos', 'Exclusivas de los gases nobles'],
   'Los semimetales combinan características de metales y no metales y se usan mucho como semiconductores.'),
  ('5677b83b-e6f6-4383-ad16-f6d8610b5a1b', 'en',
   'Compared with metals, in chemical reactions nonmetals tend to show a greater tendency to:',
   array['Gain electrons, forming anions', 'Lose electrons, forming cations', 'Not take part in any chemical bond', 'Form only metallic bonds'],
   'Nonmetals, having higher electronegativity, tend to gain electrons and form anions in ionic bonds.'),
  ('5677b83b-e6f6-4383-ad16-f6d8610b5a1b', 'es',
   'En comparación con los metales, en las reacciones químicas los no metales tienden a mostrar mayor tendencia a:',
   array['Ganar electrones, formando aniones', 'Perder electrones, formando cationes', 'No participar en ningún enlace químico', 'Formar solo enlaces metálicos'],
   'Los no metales, al tener mayor electronegatividad, tienden a ganar electrones y formar aniones en los enlaces iónicos.'),
  ('c10d4889-5d63-4e34-bbc4-163ec68a4f52', 'en',
   'Silicon, widely used to make electronic components, is classified as:',
   array['A metalloid (semimetal)', 'An alkali metal', 'A noble gas', 'A halogen'],
   'Silicon is a metalloid whose semiconductor properties make it essential to the electronics industry.'),
  ('c10d4889-5d63-4e34-bbc4-163ec68a4f52', 'es',
   'El silicio, muy utilizado en la fabricación de componentes electrónicos, se clasifica como:',
   array['Semimetal (metaloide)', 'Metal alcalino', 'Gas noble', 'Halógeno'],
   'El silicio es un semimetal cuyas propiedades de semiconductor lo hacen esencial en la industria electrónica.'),
  ('14faa6ab-4a78-44d8-bfe5-d97586bdc987', 'en',
   'In the periodic table, the periods correspond to:',
   array['The horizontal rows, indicating the number of electron shells (levels) of the atom', 'The vertical columns, indicating similar chemical properties', 'Only the metallic elements', 'Only the representative elements'],
   'Each period (horizontal row) corresponds to the number of electron shells occupied by the atoms in that row.'),
  ('14faa6ab-4a78-44d8-bfe5-d97586bdc987', 'es',
   'En la tabla periódica, los períodos corresponden:',
   array['A las filas horizontales, que indican el número de capas (niveles) electrónicas del átomo', 'A las columnas verticales, que indican propiedades químicas semejantes', 'Solo a los elementos metálicos', 'Solo a los elementos representativos'],
   'Cada período (fila horizontal) corresponde al número de capas electrónicas ocupadas por los átomos de esa fila.'),
  ('56a36418-c9ac-4f01-aedd-6e63594f7171', 'en',
   'How many periods (rows) does the current periodic table have?',
   array['7', '8', '18', '5'],
   'The modern periodic table is organized into 7 horizontal periods.'),
  ('56a36418-c9ac-4f01-aedd-6e63594f7171', 'es',
   '¿Cuántos períodos (filas) tiene la tabla periódica actual?',
   array['7', '8', '18', '5'],
   'La tabla periódica moderna está organizada en 7 períodos horizontales.'),
  ('b3feee0e-dc2b-4592-9eb4-08ccb9c3947a', 'en',
   'An element in the 3rd period of the periodic table has, in its ground state:',
   array['3 occupied electron shells', '3 valence electrons, necessarily', '3 protons in the nucleus', 'No relationship between its period and its electronic structure'],
   'The period number indicates how many electron shells the atom has, not the number of valence electrons.'),
  ('b3feee0e-dc2b-4592-9eb4-08ccb9c3947a', 'es',
   'Un elemento ubicado en el 3.er período de la tabla periódica tiene, en su estado fundamental:',
   array['3 capas electrónicas ocupadas', '3 electrones de valencia, necesariamente', '3 protones en el núcleo', 'Ninguna relación entre el período y la estructura electrónica'],
   'El número del período indica cuántas capas electrónicas tiene el átomo, no el número de electrones de valencia.'),
  ('73b2a0f4-2972-429b-915c-3833552270f7', 'en',
   'Across a period, from left to right, the atomic radius of the elements tends to:',
   array['Decrease, because of the increase in effective nuclear charge', 'Increase continuously', 'Always stay constant', 'Vary completely at random'],
   'As the atomic number increases across the period, the greater nuclear attraction on the electrons reduces the atomic radius.'),
  ('73b2a0f4-2972-429b-915c-3833552270f7', 'es',
   'A lo largo de un mismo período, de izquierda a derecha, el radio atómico de los elementos tiende a:',
   array['Disminuir, debido al aumento de la carga nuclear efectiva', 'Aumentar continuamente', 'Permanecer siempre constante', 'Variar de forma completamente aleatoria'],
   'Con el aumento del número atómico a lo largo del período, la mayor atracción nuclear sobre los electrones reduce el radio atómico.'),
  ('944e1e04-24e3-4808-b298-c49ce332687a', 'en',
   'The elements of the same period generally belong to:',
   array['Different families (groups), with different chemical properties', 'A single, identical family', 'Necessarily the same physical state', 'The same valence electron configuration'],
   'Elements of the same period have the same number of shells but belong to different families.'),
  ('944e1e04-24e3-4808-b298-c49ce332687a', 'es',
   'Los elementos de un mismo período pertenecen, en general, a:',
   array['Familias (grupos) diferentes, con propiedades químicas distintas', 'Una única y misma familia', 'Obligatoriamente el mismo estado físico', 'La misma configuración electrónica de valencia'],
   'Los elementos de un mismo período tienen el mismo número de capas, pero pertenecen a familias diferentes.'),
  ('b88cfefc-f148-4b02-8fb3-9a82d1f39a4a', 'en',
   'Going down a group (family) of the periodic table, the atomic radius tends to:',
   array['Increase, because electron shells are added', 'Decrease continuously', 'Always stay constant', 'Vary completely at random'],
   'Going down a family, the increasing number of electron shells makes the atomic radius grow.'),
  ('b88cfefc-f148-4b02-8fb3-9a82d1f39a4a', 'es',
   'A lo largo de un grupo (familia) de la tabla periódica, de arriba hacia abajo, el radio atómico tiende a:',
   array['Aumentar, debido a que se añaden capas electrónicas', 'Disminuir continuamente', 'Permanecer siempre constante', 'Variar de forma completamente aleatoria'],
   'Al descender en una familia, el aumento del número de capas electrónicas hace crecer el radio atómico.'),
  ('a9f38683-c6de-41d5-bcfe-363e55993c26', 'en',
   'The electronegativity of an element represents:',
   array['An atom''s ability to attract electrons in a chemical bond', 'The total radius of the atom', 'The energy needed to remove an electron from the atom', 'The number of neutrons in the nucleus'],
   'Electronegativity measures an atom''s tendency to attract the shared electrons in a bond toward itself.'),
  ('a9f38683-c6de-41d5-bcfe-363e55993c26', 'es',
   'La electronegatividad de un elemento representa:',
   array['La capacidad de un átomo de atraer electrones en un enlace químico', 'El radio total del átomo', 'La energía necesaria para retirar un electrón del átomo', 'La cantidad de neutrones presentes en el núcleo'],
   'La electronegatividad mide la tendencia de un átomo a atraer hacia sí los electrones compartidos en un enlace.'),
  ('3f9972f2-1468-4573-96d3-2d4e1caec6fe', 'en',
   'In general, the electronegativity of the elements across a period (from left to right) tends to:',
   array['Increase', 'Decrease', 'Stay constant', 'Follow no pattern'],
   'Across a period, the increase in effective nuclear charge generally increases the elements'' electronegativity.'),
  ('3f9972f2-1468-4573-96d3-2d4e1caec6fe', 'es',
   'En general, la electronegatividad de los elementos a lo largo de un período (de izquierda a derecha) tiende a:',
   array['Aumentar', 'Disminuir', 'Permanecer constante', 'No seguir ningún patrón'],
   'A lo largo de un período, el aumento de la carga nuclear efectiva generalmente aumenta la electronegatividad de los elementos.'),
  ('8501c01d-767e-498c-bb50-e6e793eff4b4', 'en',
   'Ionization energy is defined as the energy needed to:',
   array['Remove an electron from an atom in the gaseous state', 'Add an electron to an atom', 'Remove a proton from the nucleus', 'Melt a solid'],
   'Ionization energy measures how hard it is to remove an electron from a neutral atom, turning it into a cation.'),
  ('8501c01d-767e-498c-bb50-e6e793eff4b4', 'es',
   'La energía de ionización se define como la energía necesaria para:',
   array['Retirar un electrón de un átomo en estado gaseoso', 'Añadir un electrón a un átomo', 'Retirar un protón del núcleo', 'Fundir un sólido'],
   'La energía de ionización mide la dificultad de retirar un electrón de un átomo neutro, lo que lo convierte en un catión.'),
  ('75bfc0d2-d730-449d-a83b-80310647e171', 'en',
   'Fluorine is usually cited as the element with the highest electronegativity in the periodic table, and it is located:',
   array['Near the upper right corner of the periodic table', 'Near the lower left corner', 'At the exact center of the periodic table', 'Among the noble gases'],
   'Electronegativity tends to be highest near the upper right corner of the table (excluding the noble gases), where fluorine is.'),
  ('75bfc0d2-d730-449d-a83b-80310647e171', 'es',
   'El flúor suele señalarse como el elemento de mayor electronegatividad de la tabla periódica, y está ubicado:',
   array['Cerca de la esquina superior derecha de la tabla periódica', 'Cerca de la esquina inferior izquierda', 'En el centro exacto de la tabla periódica', 'Entre los gases nobles'],
   'La electronegatividad tiende a ser mayor cerca de la esquina superior derecha de la tabla (excluidos los gases nobles), región donde está el flúor.'),
  ('aa176b03-ddf2-4e44-a093-710ea88a94f7', 'en',
   'Thermochemistry, a branch of physical chemistry, mainly studies:',
   array['The energy (heat) exchanges that occur during chemical reactions', 'Exclusively the speed of chemical reactions', 'The electronic structure of atoms', 'The nomenclature of organic compounds'],
   'Thermochemistry analyzes the energy absorbed or released during chemical reactions.'),
  ('aa176b03-ddf2-4e44-a093-710ea88a94f7', 'es',
   'La termoquímica, rama de la fisicoquímica, estudia principalmente:',
   array['Los intercambios de energía (calor) que ocurren durante las reacciones químicas', 'Exclusivamente la velocidad de las reacciones químicas', 'La estructura electrónica de los átomos', 'La nomenclatura de los compuestos orgánicos'],
   'La termoquímica analiza la energía absorbida o liberada durante las reacciones químicas.'),
  ('5b56037c-9dd3-4230-91c1-80f7b069f8fd', 'en',
   'A chemical reaction is classified as exothermic when it:',
   array['Releases energy (heat) to the surroundings', 'Absorbs energy (heat) from the surroundings', 'Involves no energy exchange at all', 'Only occurs at very low temperatures'],
   'Exothermic reactions release energy as heat, usually warming the surroundings.'),
  ('5b56037c-9dd3-4230-91c1-80f7b069f8fd', 'es',
   'Una reacción química se clasifica como exotérmica cuando:',
   array['Libera energía (calor) al ambiente', 'Absorbe energía (calor) del ambiente', 'No implica ningún intercambio de energía', 'Ocurre solo a temperaturas muy bajas'],
   'Las reacciones exotérmicas liberan energía en forma de calor y generalmente calientan el ambiente.'),
  ('31a1a765-a8ba-41b9-b665-883853f04834', 'en',
   'Chemical kinetics mainly studies:',
   array['The speed of chemical reactions and the factors that influence it', 'Only the energy released in exothermic reactions', 'The crystal structure of solids', 'The solubility of gases in liquids'],
   'Chemical kinetics analyzes how fast reactions happen and how various factors influence them.'),
  ('31a1a765-a8ba-41b9-b665-883853f04834', 'es',
   'La cinética química estudia principalmente:',
   array['La velocidad de las reacciones químicas y los factores que la influyen', 'Solo la energía liberada en las reacciones exotérmicas', 'La estructura cristalina de los sólidos', 'La solubilidad de los gases en los líquidos'],
   'La cinética química analiza la rapidez con que ocurren las reacciones y cómo influyen en ella diversos factores.'),
  ('a4de7338-be7f-460e-aa43-78e0ef4cbe19', 'en',
   'In a chemical reaction, a catalyst mainly acts by:',
   array['Increasing the reaction rate without being consumed in the process', 'Being completely consumed during the reaction', 'Always decreasing the reaction rate', 'Changing the final product of the reaction'],
   'Catalysts speed up reactions by lowering the activation energy, without being consumed in the process.'),
  ('a4de7338-be7f-460e-aa43-78e0ef4cbe19', 'es',
   'En una reacción química, un catalizador actúa principalmente:',
   array['Aumentando la velocidad de la reacción, sin consumirse en el proceso', 'Consumiéndose por completo durante la reacción', 'Disminuyendo siempre la velocidad de la reacción', 'Alterando el producto final de la reacción'],
   'Los catalizadores aumentan la velocidad de las reacciones al disminuir la energía de activación, sin consumirse en el proceso.'),
  ('22300431-dcd2-4866-b061-4f44913d5f3f', 'en',
   'Chemical equilibrium is reached when:',
   array['The rates of the forward and reverse reactions become equal, keeping concentrations constant', 'The chemical reaction stops completely', 'All the reactants are completely converted into products', 'There is no longer any reactant or product in the system'],
   'In dynamic chemical equilibrium, the forward and reverse reactions keep happening, but at equal rates.'),
  ('22300431-dcd2-4866-b061-4f44913d5f3f', 'es',
   'El equilibrio químico se alcanza cuando:',
   array['Las velocidades de las reacciones directa e inversa se igualan y las concentraciones se mantienen constantes', 'La reacción química se detiene por completo', 'Todos los reactivos se convierten totalmente en productos', 'Ya no queda ningún reactivo ni producto en el sistema'],
   'En el equilibrio químico dinámico, las reacciones directa e inversa siguen ocurriendo, pero a velocidades iguales.'),
  ('875829df-5802-4639-abf3-9648abc6a78c', 'en',
   'pH is a scale used to measure:',
   array['The acidity or basicity of an aqueous solution', 'The temperature of a solution', 'The density of a solution', 'The color of a solution'],
   'pH measures the concentration of H⁺ ions in a solution, indicating how acidic or basic it is.'),
  ('875829df-5802-4639-abf3-9648abc6a78c', 'es',
   'El pH es una escala que se usa para medir:',
   array['La acidez o basicidad de una solución acuosa', 'La temperatura de una solución', 'La densidad de una solución', 'El color de una solución'],
   'El pH mide la concentración de iones H⁺ en una solución e indica su grado de acidez o basicidad.'),
  ('5f62f3ba-99fb-45d1-ad97-bb4ae65a8238', 'en',
   'A solution with a pH of 7, at 25°C, is classified as:',
   array['Neutral', 'Acidic', 'Basic (alkaline)', 'Impossible'],
   'A pH of 7, at 25°C, is the neutral point of the scale, characteristic of pure water.'),
  ('5f62f3ba-99fb-45d1-ad97-bb4ae65a8238', 'es',
   'Una solución con pH igual a 7, a 25°C, se clasifica como:',
   array['Neutra', 'Ácida', 'Básica (alcalina)', 'Imposible de existir'],
   'El valor de pH 7, a 25°C, corresponde al punto neutro de la escala, característico del agua pura.'),
  ('e7866419-b2e1-4b9e-97d0-e981df01eb7d', 'en',
   'Electrochemistry is the branch of physical chemistry that studies the relationship between:',
   array['Chemical reactions and the generation or consumption of electrical energy', 'Chemical reactions and the color of compounds', 'The bone structure of living beings', 'Exclusively mechanical phenomena'],
   'Electrochemistry studies processes such as cells and batteries, and electrolysis.'),
  ('e7866419-b2e1-4b9e-97d0-e981df01eb7d', 'es',
   'La electroquímica es la rama de la fisicoquímica que estudia la relación entre:',
   array['Las reacciones químicas y la generación o el consumo de energía eléctrica', 'Las reacciones químicas y el color de los compuestos', 'La estructura ósea de los seres vivos', 'Fenómenos exclusivamente mecánicos'],
   'La electroquímica estudia procesos como las pilas, las baterías y la electrólisis.'),
  ('5ffcd571-f71e-4f8d-a896-1481d6e65c83', 'en',
   'An ionic bond typically forms between:',
   array['A metal and a nonmetal, with a transfer of electrons', 'Two nonmetals, with a sharing of electrons', 'Two metals, with a sharing of electrons', 'Two noble gases, with no interaction at all'],
   'In an ionic bond, a metal gives electrons to a nonmetal, forming a cation and an anion that attract each other electrostatically.'),
  ('5ffcd571-f71e-4f8d-a896-1481d6e65c83', 'es',
   'El enlace iónico ocurre, típicamente, entre:',
   array['Un metal y un no metal, con transferencia de electrones', 'Dos no metales, con compartición de electrones', 'Dos metales, con compartición de electrones', 'Dos gases nobles, sin ninguna interacción'],
   'En el enlace iónico, un metal cede electrones a un no metal y se forman un catión y un anión que se atraen electrostáticamente.'),
  ('bef2ace4-59ee-4398-bba0-cf8f5350c9fe', 'en',
   'A covalent bond is characterized by:',
   array['The sharing of electron pairs between atoms', 'The complete transfer of electrons from one atom to another', 'The complete absence of electrons involved', 'A bond exclusively between metals'],
   'In a covalent bond, atoms share pairs of electrons, usually between nonmetals.'),
  ('bef2ace4-59ee-4398-bba0-cf8f5350c9fe', 'es',
   'El enlace covalente se caracteriza por:',
   array['La compartición de pares de electrones entre los átomos', 'La transferencia total de electrones de un átomo a otro', 'La ausencia completa de electrones involucrados', 'La unión exclusiva entre metales'],
   'En el enlace covalente, los átomos comparten pares de electrones, generalmente entre no metales.'),
  ('e5da1605-6d0a-42ff-abf9-b368c4f9341e', 'en',
   'The metallic bond, responsible for properties such as the electrical conductivity and malleability of metals, is often described as:',
   array['A "sea" of free electrons surrounding the metal cations', 'A permanent transfer of electrons between neighboring atoms', 'A rigid sharing of electrons between only two atoms', 'The complete absence of free electrons in the structure'],
   'In a metallic bond, the valence electrons form a delocalized "sea" shared by all the metal cations.'),
  ('e5da1605-6d0a-42ff-abf9-b368c4f9341e', 'es',
   'El enlace metálico, responsable de propiedades como la conductividad eléctrica y la maleabilidad de los metales, suele describirse como:',
   array['Un "mar de electrones" libres que envuelve a los cationes metálicos', 'Una transferencia definitiva de electrones entre átomos vecinos', 'Una compartición rígida de electrones entre solo dos átomos', 'La ausencia total de electrones libres en la estructura'],
   'En el enlace metálico, los electrones de valencia forman un "mar" deslocalizado, compartido por todos los cationes metálicos.'),
  ('da85b405-37fa-417f-9191-2a9d5d5dd3d4', 'en',
   'The Octet Rule states that atoms tend to become stable when they reach, in the valence shell:',
   array['Eight electrons, similar to the configuration of the noble gases', 'Only one electron, similar to the alkali metals', 'Exactly four electrons, always', 'No electrons in the valence shell'],
   'The Octet Rule proposes that atoms seek 8 electrons in the valence shell, reaching a stability similar to that of the noble gases.'),
  ('da85b405-37fa-417f-9191-2a9d5d5dd3d4', 'es',
   'La Regla del Octeto establece que los átomos tienden a estabilizarse cuando alcanzan, en la capa de valencia:',
   array['Ocho electrones, semejante a la configuración de los gases nobles', 'Solo un electrón, semejante a los metales alcalinos', 'Exactamente cuatro electrones, siempre', 'Ningún electrón en la capa de valencia'],
   'La Regla del Octeto propone que los átomos buscan alcanzar 8 electrones en la capa de valencia, logrando una estabilidad semejante a la de los gases nobles.'),
  ('6c81e005-2f56-4660-bfc9-c57b473462e3', 'en',
   'A covalent bond is classified as polar when it forms between atoms:',
   array['With different electronegativities, creating an uneven distribution of charge', 'With identical electronegativities', 'Always of the same chemical element', 'With no possible difference in electronegativity'],
   'The difference in electronegativity between the bonded atoms creates an electric dipole, which characterizes a polar covalent bond.'),
  ('6c81e005-2f56-4660-bfc9-c57b473462e3', 'es',
   'Un enlace covalente se clasifica como polar cuando ocurre entre átomos:',
   array['De electronegatividades diferentes, lo que genera una distribución desigual de carga', 'De electronegatividades idénticas', 'Siempre del mismo elemento químico', 'Sin ninguna diferencia de electronegatividad posible'],
   'La diferencia de electronegatividad entre los átomos enlazados genera un dipolo eléctrico, lo que caracteriza el enlace covalente polar.'),
  ('ac0a6fda-8ad9-45e4-8952-27bab2a14e57', 'en',
   'Molecular geometries, studied by the Valence Shell Electron Pair Repulsion (VSEPR) theory, are determined mainly by:',
   array['The repulsion between the electron pairs around the central atom', 'The total mass of the molecule', 'The color of the substance', 'The physical state of the compound'],
   'VSEPR theory is based on the idea that electron pairs arrange themselves to minimize the repulsion between them.'),
  ('ac0a6fda-8ad9-45e4-8952-27bab2a14e57', 'es',
   'Las geometrías moleculares, estudiadas por la Teoría de Repulsión de Pares de Electrones de la Capa de Valencia (TRPECV o VSEPR), están determinadas principalmente por:',
   array['La repulsión entre los pares de electrones alrededor del átomo central', 'La masa total de la molécula', 'El color de la sustancia', 'El estado físico del compuesto'],
   'La teoría VSEPR se basa en la idea de que los pares de electrones se organizan de modo que se minimice la repulsión entre ellos.'),
  ('2ea316dc-b56d-437c-ad38-de01071fc4e3', 'en',
   'Intermolecular forces, which hold molecules together in liquids and molecular solids, include, among others:',
   array['Hydrogen bonds, dipole-dipole interactions and London (induced dipole) forces', 'Only ionic bonds', 'Only metallic bonds', 'No force other than the internal covalent bonds'],
   'Intermolecular forces act between separate molecules, unlike the internal covalent bonds.'),
  ('2ea316dc-b56d-437c-ad38-de01071fc4e3', 'es',
   'Las fuerzas intermoleculares, responsables de mantener unidas las moléculas en los líquidos y sólidos moleculares, incluyen, entre otras:',
   array['Los puentes de hidrógeno, las interacciones dipolo-dipolo y las fuerzas de London (dipolo inducido)', 'Solo los enlaces iónicos', 'Solo los enlaces metálicos', 'Ninguna fuerza además de los enlaces covalentes internos'],
   'Las fuerzas intermoleculares actúan entre moléculas distintas, a diferencia de los enlaces covalentes internos.'),
  ('00d56428-94d8-4c5d-bd72-4fc837bc063c', 'en',
   'Water has a relatively high boiling point for such a small molecule, mainly because of the presence of:',
   array['Hydrogen bonds between its molecules', 'Strong ionic bonds between the hydrogen and oxygen atoms', 'A complete absence of intermolecular forces', 'Metallic bonds between its molecules'],
   'The strong hydrogen bonds between water molecules require more energy to break, raising its boiling point.'),
  ('00d56428-94d8-4c5d-bd72-4fc837bc063c', 'es',
   'El agua tiene un punto de ebullición relativamente elevado para una molécula tan pequeña, principalmente debido a la presencia de:',
   array['Puentes de hidrógeno entre sus moléculas', 'Enlaces iónicos fuertes entre los átomos de hidrógeno y oxígeno', 'La ausencia total de fuerzas intermoleculares', 'Enlaces metálicos entre sus moléculas'],
   'Los fuertes puentes de hidrógeno entre las moléculas de agua exigen más energía para romperse, lo que eleva su punto de ebullición.'),
  ('18072644-1ad1-40d1-b0a3-6fd1f0d4b8ff', 'en',
   'Acid rain is an environmental phenomenon caused mainly by the atmospheric emission of:',
   array['Sulfur and nitrogen oxides, from burning fossil fuels', 'Pure water vapor', 'Excess oxygen gas', 'Noble gases emitted by industries'],
   'Sulfur and nitrogen oxides, released by burning fossil fuels, react with atmospheric water to form acids.'),
  ('18072644-1ad1-40d1-b0a3-6fd1f0d4b8ff', 'es',
   'La lluvia ácida es un fenómeno ambiental causado principalmente por la emisión a la atmósfera de:',
   array['Óxidos de azufre y nitrógeno, provenientes de la quema de combustibles fósiles', 'Vapor de agua puro', 'Gas oxígeno en exceso', 'Gases nobles emitidos por las industrias'],
   'Los óxidos de azufre y nitrógeno, liberados por la quema de combustibles fósiles, reaccionan con el agua atmosférica y forman ácidos.'),
  ('078927aa-500e-4efc-ac40-ccb77ca2588e', 'en',
   'The greenhouse effect, a natural phenomenon intensified by human activities, is directly related to the rising atmospheric concentration of gases such as:',
   array['Carbon dioxide (CO₂) and methane (CH₄)', 'Noble gases, such as helium and neon', 'Only water vapor, exclusively', 'Pure molecular nitrogen (N₂)'],
   'The increase in gases such as CO₂ and CH₄ from human activities intensifies the greenhouse effect.'),
  ('078927aa-500e-4efc-ac40-ccb77ca2588e', 'es',
   'El efecto invernadero, fenómeno natural intensificado por las actividades humanas, está directamente relacionado con el aumento de la concentración atmosférica de gases como:',
   array['Dióxido de carbono (CO₂) y metano (CH₄)', 'Gases nobles, como el helio y el neón', 'Solo vapor de agua, exclusivamente', 'Nitrógeno molecular (N₂) puro'],
   'El aumento de gases como el CO₂ y el CH₄, provenientes de las actividades humanas, intensifica el efecto invernadero.'),
  ('f036a9ae-f57e-48c5-ae0d-ddbfa0589d8d', 'en',
   'The ozone layer, located in the stratosphere, plays a key role by:',
   array['Absorbing part of the harmful ultraviolet radiation coming from the Sun', 'Producing oxygen for the respiration of all living beings', 'Completely blocking visible light from reaching Earth', 'Having nothing to do with solar radiation'],
   'Stratospheric ozone absorbs much of the harmful ultraviolet radiation, protecting living beings.'),
  ('f036a9ae-f57e-48c5-ae0d-ddbfa0589d8d', 'es',
   'La capa de ozono, ubicada en la estratosfera, tiene un papel fundamental al:',
   array['Absorber parte de la radiación ultravioleta perjudicial proveniente del Sol', 'Producir oxígeno para la respiración de todos los seres vivos', 'Impedir por completo la entrada de luz visible a la Tierra', 'No tener ninguna relación con la radiación solar'],
   'El ozono estratosférico absorbe gran parte de la radiación ultravioleta nociva y protege a los seres vivos.'),
  ('e33515ed-c9af-42f1-94e2-f3d2757b929b', 'en',
   'Substances such as CFCs (chlorofluorocarbons), formerly used in aerosols and refrigerators, were associated mainly with:',
   array['The destruction of the ozone layer', 'An immediate increase in soil fertility', 'The purification of drinking water', 'A reduction in the greenhouse effect'],
   'CFCs release chlorine atoms in the stratosphere, which catalyze the breakdown of ozone.'),
  ('e33515ed-c9af-42f1-94e2-f3d2757b929b', 'es',
   'Sustancias como los CFC (clorofluorocarbonos), usadas antiguamente en aerosoles y refrigeradores, se asociaron principalmente a:',
   array['La destrucción de la capa de ozono', 'El aumento inmediato de la fertilidad del suelo', 'La purificación del agua potable', 'La reducción del efecto invernadero'],
   'Los CFC liberan átomos de cloro en la estratosfera, que catalizan la descomposición del ozono.'),
  ('3b930a78-d9c3-4e77-8b59-ffb4333e73d0', 'en',
   'Treating water for human consumption usually includes, among other steps:',
   array['Chlorination, to eliminate disease-causing microorganisms', 'Adding heavy metals, for purification', 'Removing every substance dissolved in the water', 'Direct exposure to nuclear radiation'],
   'Chlorination is a common step in water treatment, used for disinfection and to eliminate microorganisms.'),
  ('3b930a78-d9c3-4e77-8b59-ffb4333e73d0', 'es',
   'El tratamiento del agua para consumo humano incluye generalmente, entre otras etapas, la:',
   array['Cloración, para eliminar microorganismos patógenos', 'Adición de metales pesados, para purificarla', 'Eliminación total de cualquier sustancia disuelta en el agua', 'Exposición directa a radiación nuclear'],
   'La cloración es una etapa común en el tratamiento del agua, usada para la desinfección y la eliminación de microorganismos.'),
  ('c12cafa6-40ca-41d7-bc6b-f47dce89db12', 'en',
   'Recycling materials such as plastic, glass, paper and metal helps, among other benefits, to:',
   array['Reduce the extraction of natural resources and the volume of waste in landfills', 'Only increase production costs, with no environmental benefit', 'Completely eliminate the need for sewage treatment', 'Have no relevant environmental impact at all'],
   'Recycling reduces the demand for virgin raw materials and cuts the amount of waste thrown away.'),
  ('c12cafa6-40ca-41d7-bc6b-f47dce89db12', 'es',
   'El reciclaje de materiales como plástico, vidrio, papel y metal contribuye, entre otros beneficios, a:',
   array['Reducir la extracción de recursos naturales y el volumen de residuos en los vertederos', 'Solo aumentar los costos de producción, sin ningún beneficio ambiental', 'Eliminar por completo la necesidad de tratar las aguas residuales', 'No tener ningún impacto ambiental relevante'],
   'El reciclaje reduce la demanda de materias primas vírgenes y disminuye la cantidad de residuos desechados.'),
  ('019969c4-946e-495d-86de-9cc42dd8ed07', 'en',
   'Pesticides, widely used in agriculture, can pose environmental and human health risks mainly through:',
   array['Contamination of soil, water and food, as well as direct toxic effects', 'No risk at all, being completely harmless substances', 'Natural purification of the environment where they are applied', 'A reduction in air pollution'],
   'Excessive or improper use of pesticides can contaminate soil, water and food, as well as cause toxic effects.'),
  ('019969c4-946e-495d-86de-9cc42dd8ed07', 'es',
   'Los agrotóxicos (plaguicidas), muy usados en la agricultura, pueden traer riesgos ambientales y para la salud humana principalmente a través de:',
   array['La contaminación del suelo, del agua y de los alimentos, además de efectos tóxicos directos', 'Ningún tipo de riesgo, pues son sustancias totalmente inofensivas', 'La purificación natural del ambiente donde se aplican', 'La reducción de la contaminación atmosférica'],
   'El uso excesivo o inadecuado de plaguicidas puede contaminar el suelo, el agua y los alimentos, además de causar efectos tóxicos.'),
  ('5e0815e0-52f2-4a18-824e-6f219a3b7260', 'en',
   'Batteries disposed of improperly are an environmental risk mainly because they contain:',
   array['Toxic heavy metals, such as lead, mercury and cadmium', 'Only pure water', 'Completely biodegradable, harmless substances', 'No harmful chemical components'],
   'Batteries contain heavy metals that, if disposed of incorrectly, can contaminate the soil and groundwater.'),
  ('5e0815e0-52f2-4a18-824e-6f219a3b7260', 'es',
   'Las pilas y baterías desechadas de forma inadecuada representan un riesgo ambiental principalmente porque contienen:',
   array['Metales pesados tóxicos, como plomo, mercurio y cadmio', 'Solo agua pura en su composición', 'Sustancias totalmente biodegradables e inofensivas', 'Ningún componente químico perjudicial'],
   'Las pilas y baterías contienen metales pesados que, si se desechan de forma incorrecta, pueden contaminar el suelo y las aguas subterráneas.'),
  ('a0dec77e-1717-4805-a318-d92e506f72ad', 'en',
   'According to Arrhenius''s definition, acids are substances that, in aqueous solution, release as their only cation:',
   array['H⁺ ions (or H₃O⁺)', 'OH⁻ ions', 'Metal ions', 'Free electrons'],
   'According to Arrhenius, acids are substances that release H⁺ ions when they dissociate in water.'),
  ('a0dec77e-1717-4805-a318-d92e506f72ad', 'es',
   'Según la definición de Arrhenius, los ácidos son sustancias que, en solución acuosa, liberan como único catión:',
   array['Iones H⁺ (o H₃O⁺)', 'Iones OH⁻', 'Iones metálicos', 'Electrones libres'],
   'Según Arrhenius, los ácidos son sustancias que, al disociarse en agua, liberan iones H⁺.'),
  ('3c12bd0a-6bff-4d4f-bd16-0e1fec79947c', 'en',
   'According to Arrhenius''s definition, bases are substances that, in aqueous solution, release as their only anion:',
   array['OH⁻ (hydroxide) ions', 'H⁺ ions', 'Metal ions', 'Free electrons'],
   'According to Arrhenius, bases release hydroxide (OH⁻) ions when they dissociate in water.'),
  ('3c12bd0a-6bff-4d4f-bd16-0e1fec79947c', 'es',
   'Según la definición de Arrhenius, las bases son sustancias que, en solución acuosa, liberan como único anión:',
   array['Iones OH⁻ (hidroxilo)', 'Iones H⁺', 'Iones metálicos', 'Electrones libres'],
   'Según Arrhenius, las bases liberan iones hidroxilo (OH⁻) al disociarse en agua.'),
  ('3e58ec85-4332-4c33-8fc0-14f452a81003', 'en',
   'The reaction between an acid and a base, producing a salt and water, is called:',
   array['A neutralization reaction', 'A combustion reaction', 'A redox reaction, exclusively', 'A polymerization reaction'],
   'Neutralization is the characteristic reaction between acids and bases, producing a salt and water.'),
  ('3e58ec85-4332-4c33-8fc0-14f452a81003', 'es',
   'La reacción entre un ácido y una base, que produce sal y agua, se llama:',
   array['Reacción de neutralización', 'Reacción de combustión', 'Reacción redox, exclusivamente', 'Reacción de polimerización'],
   'La neutralización es la reacción característica entre ácidos y bases, que forma una sal y agua como productos.'),
  ('6fbd1a48-8c02-4e39-b86d-7cb0c05a7077', 'en',
   'Sodium chloride (NaCl), table salt, is chemically classified as:',
   array['A salt, theoretically resulting from the reaction between an acid and a base', 'A strong acid', 'A strong base', 'An oxide'],
   'NaCl is a salt, formed by the cation of a base (Na⁺) and the anion of an acid (Cl⁻).'),
  ('6fbd1a48-8c02-4e39-b86d-7cb0c05a7077', 'es',
   'El cloruro de sodio (NaCl), la sal de mesa, se clasifica químicamente como:',
   array['Una sal, resultante teóricamente de la reacción entre un ácido y una base', 'Un ácido fuerte', 'Una base fuerte', 'Un óxido'],
   'El NaCl es una sal, formada por el catión de una base (Na⁺) y el anión de un ácido (Cl⁻).'),
  ('ebfce110-30e2-460b-b064-099ba803d786', 'en',
   'Oxides are binary compounds formed by combining oxygen with:',
   array['Another chemical element, except fluorine', 'Exclusively noble metals', 'Only hydrogen', 'No element other than oxygen itself'],
   'Oxides are binary compounds of oxygen with another element (except fluorine).'),
  ('ebfce110-30e2-460b-b064-099ba803d786', 'es',
   'Los óxidos son compuestos binarios formados por la combinación del oxígeno con:',
   array['Otro elemento químico, excepto el flúor', 'Exclusivamente metales nobles', 'Solo hidrógeno', 'Ningún otro elemento además del propio oxígeno'],
   'Los óxidos son compuestos binarios del oxígeno con otro elemento (excepto el flúor).'),
  ('fbcef643-2be5-4df5-b522-13ba9fbeba94', 'en',
   'Carbon dioxide (CO₂), a well-known oxide, is classified as an oxide that is:',
   array['Acidic, because it reacts with water to form an acid', 'Basic, because it reacts with water to form a strong base', 'Neutral, with no reactivity at all', 'Amphoteric, exclusively'],
   'CO₂ reacts with water to form carbonic acid (H₂CO₃), so it is classified as an acidic oxide.'),
  ('fbcef643-2be5-4df5-b522-13ba9fbeba94', 'es',
   'El dióxido de carbono (CO₂), un óxido muy conocido, se clasifica como un óxido:',
   array['Ácido, pues reacciona con el agua formando un ácido', 'Básico, pues reacciona con el agua formando una base fuerte', 'Neutro, sin ninguna reactividad', 'Anfótero, exclusivamente'],
   'El CO₂ reacciona con el agua formando ácido carbónico (H₂CO₃), por lo que se clasifica como óxido ácido.'),
  ('7562b6c0-25d5-4509-b90f-27d627c97699', 'en',
   'Sulfuric acid (H₂SO₄), one of the most industrially produced inorganic acids, is widely used, among other applications, in:',
   array['Car batteries and the fertilizer industry', 'Alcoholic beverages', 'Moisturizing cosmetics, exclusively', 'Fresh foods'],
   'Sulfuric acid is essential in making lead-acid batteries and in producing phosphate fertilizers.'),
  ('7562b6c0-25d5-4509-b90f-27d627c97699', 'es',
   'El ácido sulfúrico (H₂SO₄), uno de los ácidos inorgánicos más producidos industrialmente, se usa ampliamente, entre otras aplicaciones, en:',
   array['Las baterías de autos y la industria de fertilizantes', 'Las bebidas alcohólicas', 'Los cosméticos hidratantes, exclusivamente', 'Los alimentos frescos'],
   'El ácido sulfúrico es esencial en la fabricación de baterías de plomo-ácido y en la producción de fertilizantes fosfatados.'),
  ('ecd77042-24ed-4067-9cc1-93f6a7313667', 'en',
   'Sodium hydroxide (NaOH), a strong base widely used in industry, is popularly known as:',
   array['Caustic soda', 'Vinegar', 'Table salt', 'Baking soda'],
   'NaOH, sold as caustic soda, is used to make soap and paper and in industrial cleaning processes.'),
  ('ecd77042-24ed-4067-9cc1-93f6a7313667', 'es',
   'El hidróxido de sodio (NaOH), base fuerte muy usada en la industria, se conoce popularmente como:',
   array['Soda cáustica', 'Vinagre', 'Sal de mesa', 'Bicarbonato de sodio'],
   'El NaOH, llamado comercialmente soda cáustica, se usa en la fabricación de jabones y papel y en procesos de limpieza industrial.'),
  ('af8fdd35-3bc4-415a-8a26-61ba4d71beee', 'en',
   'The carbon atom can form long and varied chains mainly because it:',
   array['Has 4 valence electrons, forming up to 4 stable covalent bonds', 'Has only 1 valence electron', 'Is a highly reactive metal', 'Does not form bonds with other carbon atoms'],
   'Carbon''s tetravalence allows it to form long, branched and cyclic chains, the basis of organic chemistry.'),
  ('af8fdd35-3bc4-415a-8a26-61ba4d71beee', 'es',
   'El átomo de carbono es capaz de formar cadenas largas y variadas principalmente porque:',
   array['Tiene 4 electrones de valencia y forma hasta 4 enlaces covalentes estables', 'Tiene solo 1 electrón de valencia', 'Es un metal muy reactivo', 'No forma enlaces con otros átomos de carbono'],
   'La tetravalencia del carbono permite formar cadenas largas, ramificadas y cíclicas, base de la química orgánica.'),
  ('17295803-8ffe-4f66-904f-51f915727eaf', 'en',
   'A carbon chain is classified as open (acyclic) when it:',
   array['Does not form a closed ring of carbon atoms', 'Necessarily forms a closed ring', 'Contains only hydrogen atoms', 'Contains no carbon atoms'],
   'Open chains have free ends and do not form a closed ring, unlike cyclic chains.'),
  ('17295803-8ffe-4f66-904f-51f915727eaf', 'es',
   'Una cadena carbonada se clasifica como abierta (acíclica) cuando:',
   array['No forma un ciclo cerrado de átomos de carbono', 'Forma obligatoriamente un anillo cerrado', 'Contiene solo átomos de hidrógeno', 'No contiene ningún átomo de carbono'],
   'Las cadenas abiertas tienen extremos libres, sin formar un anillo cerrado, a diferencia de las cadenas cíclicas.'),
  ('442823be-8568-4013-9745-384bfe3a5b18', 'en',
   'A carbon chain is classified as saturated when it:',
   array['Has only single bonds between the carbon atoms', 'Has at least one double or triple bond', 'Contains only oxygen atoms', 'Is always a cyclic chain'],
   'Saturated chains have only single bonds between carbons, with no double or triple bonds.'),
  ('442823be-8568-4013-9745-384bfe3a5b18', 'es',
   'Una cadena carbonada se clasifica como saturada cuando:',
   array['Tiene solo enlaces simples entre los átomos de carbono', 'Tiene al menos un enlace doble o triple', 'Contiene solo átomos de oxígeno', 'Es siempre una cadena cíclica'],
   'Las cadenas saturadas tienen exclusivamente enlaces simples entre los carbonos, sin dobles ni triples.'),
  ('035ba02d-20e2-4e2a-8265-375952bf3ba3', 'en',
   'A homogeneous carbon chain is one that contains:',
   array['Only carbon atoms in the main chain, with no heteroatoms', 'At least one heteroatom (such as oxygen or nitrogen) in the main chain', 'Only double bonds', 'An odd number of carbon atoms'],
   'Homogeneous chains have no heteroatoms interrupting the sequence of carbon atoms in the main chain.'),
  ('035ba02d-20e2-4e2a-8265-375952bf3ba3', 'es',
   'Una cadena carbonada homogénea es aquella que contiene:',
   array['Solo átomos de carbono en la cadena principal, sin heteroátomos', 'Al menos un heteroátomo (como oxígeno o nitrógeno) en la cadena principal', 'Exclusivamente enlaces dobles', 'Un número impar de átomos de carbono'],
   'Las cadenas homogéneas no tienen heteroátomos que interrumpan la secuencia de átomos de carbono de la cadena principal.'),
  ('b7197c40-fcf9-4a30-b420-b669708eb769', 'en',
   'A carbon classified as "tertiary" in a carbon chain is directly bonded to:',
   array['Three other carbon atoms', 'A single carbon atom', 'Two carbon atoms', 'Four carbon atoms'],
   'A carbon''s classification depends on how many other carbons are directly bonded to it; a tertiary carbon is bonded to three.'),
  ('b7197c40-fcf9-4a30-b420-b669708eb769', 'es',
   'Un carbono clasificado como "terciario", en una cadena carbonada, está unido directamente a:',
   array['Otros tres átomos de carbono', 'Un único átomo de carbono', 'Dos átomos de carbono', 'Cuatro átomos de carbono'],
   'La clasificación del carbono depende del número de otros carbonos unidos directamente a él; el terciario está unido a tres.'),
  ('15cf7820-fdb3-412c-a0f5-fcc28f8b47d6', 'en',
   'The aldehyde functional group is characterized by a carbonyl group (C=O) bonded to:',
   array['A hydrogen atom and at most one organic group, always at the end of the chain', 'Two organic groups, with no hydrogen', 'A hydroxyl group', 'A nitrogen atom'],
   'In an aldehyde, the carbonyl is always at the end of the chain, bonded to at least one hydrogen.'),
  ('15cf7820-fdb3-412c-a0f5-fcc28f8b47d6', 'es',
   'La función orgánica aldehído se caracteriza por la presencia del grupo carbonilo (C=O) unido a:',
   array['Un átomo de hidrógeno y, como máximo, un radical orgánico, siempre en el extremo de la cadena', 'Dos radicales orgánicos, sin hidrógeno', 'Un grupo hidroxilo', 'Un átomo de nitrógeno'],
   'En el aldehído, el carbonilo está siempre en el extremo de la cadena, unido a al menos un hidrógeno.'),
  ('5db78570-9815-458b-8819-c065e498cc4f', 'en',
   'Formaldehyde (methanal), one of the simplest aldehydes, is widely known for its use in:',
   array['Preservative solutions for biological tissue (formalin)', 'Alcoholic beverages', 'Artificial sweeteners', 'Car fuels'],
   'Formaldehyde, in aqueous solution (formalin), is used as a preservative for biological tissue and as a disinfectant.'),
  ('5db78570-9815-458b-8819-c065e498cc4f', 'es',
   'El formaldehído (metanal), uno de los aldehídos más simples, es muy conocido por su uso en:',
   array['Soluciones conservantes de tejidos biológicos (formol)', 'Bebidas alcohólicas', 'Edulcorantes artificiales', 'Combustibles para autos'],
   'El formaldehído, en solución acuosa (formol), se usa como conservante de tejidos biológicos y desinfectante.'),
  ('ca6b53f0-ad1a-4d96-a328-23f08a49e68e', 'en',
   'Acetaldehyde (ethanal) is an important intermediate compound formed during:',
   array['The metabolism of ethyl alcohol in the human body', 'Photosynthesis in plants', 'The formation of noble gases', 'The industrial production of table salt'],
   'In the liver, ethanol is metabolized into acetaldehyde, a substance associated with many of the negative effects of a hangover.'),
  ('ca6b53f0-ad1a-4d96-a328-23f08a49e68e', 'es',
   'El acetaldehído (etanal) es un compuesto intermedio importante que se forma durante:',
   array['El metabolismo del alcohol etílico en el organismo humano', 'La fotosíntesis de las plantas', 'La formación de gases nobles', 'La producción industrial de sal de mesa'],
   'En el hígado, el etanol se metaboliza en acetaldehído, sustancia asociada a muchos de los efectos negativos de la resaca.'),
  ('d76e96fe-f2dc-49ba-991b-e6c7789d776e', 'en',
   'Aldehydes can be identified in the laboratory with specific tests, such as Tollens'' test, which relies on their ability to act as:',
   array['Reducing agents', 'Strong oxidizing agents', 'Strong bases', 'Completely inert substances'],
   'Aldehydes are easily oxidized, acting as reducing agents in reactions such as Tollens'' test (the silver mirror).'),
  ('d76e96fe-f2dc-49ba-991b-e6c7789d776e', 'es',
   'Los aldehídos pueden identificarse en el laboratorio mediante pruebas específicas, como la prueba de Tollens, que se basa en su capacidad de actuar como:',
   array['Agentes reductores', 'Agentes oxidantes fuertes', 'Bases fuertes', 'Sustancias completamente inertes'],
   'Los aldehídos se oxidan fácilmente y actúan como agentes reductores en reacciones como la prueba de Tollens (espejo de plata).'),
  ('dfdc7121-6a80-4a7e-add0-ec19326658cc', 'en',
   'Vanillin, the compound responsible for the characteristic aroma of vanilla, belongs to which organic function?',
   array['Aldehyde', 'Ether', 'Amine', 'Carboxylic acid'],
   'Vanillin has an aldehyde group in its structure and is one of the best-known natural aromatic compounds.'),
  ('dfdc7121-6a80-4a7e-add0-ec19326658cc', 'es',
   'La vainillina, compuesto responsable del aroma característico de la vainilla, pertenece a la función orgánica:',
   array['Aldehído', 'Éter', 'Amina', 'Ácido carboxílico'],
   'La vainillina tiene un grupo aldehído en su estructura y es uno de los compuestos aromáticos naturales más conocidos.'),
  ('b776c21f-156d-43dc-a581-ff77af53d672', 'en',
   'The amide functional group is characterized by the combination of:',
   array['A carbonyl (C=O) bonded to a nitrogen atom', 'A hydroxyl bonded to a nitrogen atom', 'Two oxygen atoms bonded to the same carbon', 'A sulfur atom bonded to carbon'],
   'An amide has the -CONH₂ group (or variations), with the carbonyl directly bonded to nitrogen.'),
  ('b776c21f-156d-43dc-a581-ff77af53d672', 'es',
   'La función orgánica amida se caracteriza por la presencia del grupo funcional formado por la combinación de:',
   array['Un carbonilo (C=O) unido a un átomo de nitrógeno', 'Un hidroxilo unido a un átomo de nitrógeno', 'Dos átomos de oxígeno unidos al mismo carbono', 'Un átomo de azufre unido al carbono'],
   'La amida tiene el grupo -CONH₂ (o variaciones), con el carbonilo unido directamente al nitrógeno.'),
  ('2a56051b-4adf-44ee-955c-921ee4e2ec5b', 'en',
   'Peptide bonds, which link amino acids together to form proteins, are structurally classified as:',
   array['Amides', 'Esters', 'Ethers', 'Ketones'],
   'Chemically, the peptide bond is an amide formed between the carboxyl group of one amino acid and the amine group of another.'),
  ('2a56051b-4adf-44ee-955c-921ee4e2ec5b', 'es',
   'Los enlaces peptídicos, responsables de unir los aminoácidos para formar proteínas, se clasifican estructuralmente como:',
   array['Amidas', 'Ésteres', 'Éteres', 'Cetonas'],
   'Químicamente, el enlace peptídico es una amida formada entre el grupo carboxilo de un aminoácido y el grupo amino de otro.'),
  ('4196bf57-85ef-4f7e-9c16-27206c1d9c6e', 'en',
   'Urea, an important nitrogen compound eliminated from the human body in urine, is classified as a:',
   array['Diamide', 'Simple ester', 'Aromatic ketone', 'Purely inorganic substance'],
   'Urea has two amide groups bonded to the same central carbon atom, so it is classified as a diamide.'),
  ('4196bf57-85ef-4f7e-9c16-27206c1d9c6e', 'es',
   'La urea, importante compuesto nitrogenado que el organismo humano elimina en la orina, se clasifica como una:',
   array['Diamida', 'Éster simple', 'Cetona aromática', 'Sustancia exclusivamente inorgánica'],
   'La urea tiene dos grupos amida unidos a un mismo átomo de carbono central, por lo que se clasifica como diamida.'),
  ('aadd7505-bd14-4fdb-9946-fed3f28effc5', 'en',
   'Unlike amines, amides are generally:',
   array['Much less basic, being considered practically neutral', 'Far more basic than amines', 'Strongly acidic, like strong mineral acids', 'Identical to amines, with no difference'],
   'The carbonyl next to the nitrogen makes its electron pair less available, which makes amides much less basic.'),
  ('aadd7505-bd14-4fdb-9946-fed3f28effc5', 'es',
   'A diferencia de las aminas, las amidas tienen generalmente un carácter:',
   array['Mucho menos básico, por lo que se consideran prácticamente neutras', 'Mucho más básico que las aminas', 'Fuertemente ácido, semejante al de los ácidos minerales fuertes', 'Idéntico al de las aminas, sin ninguna diferencia'],
   'La presencia del carbonilo junto al nitrógeno reduce la disponibilidad del par de electrones, lo que hace que las amidas sean mucho menos básicas.'),
  ('52714ff4-bc7a-418d-81a6-9b7e6098b167', 'en',
   'Paracetamol (acetaminophen), one of the most widely used painkillers in the world, has in its chemical structure the function:',
   array['Amide, among other functions present in the molecule', 'Only pure hydrocarbon, with no other functions', 'Only a noble gas bonded to carbon', 'No recognized organic function'],
   'Paracetamol has an amide group in its molecular structure, as well as other organic functions.'),
  ('52714ff4-bc7a-418d-81a6-9b7e6098b167', 'es',
   'El paracetamol, uno de los analgésicos más usados del mundo, tiene en su estructura química la función:',
   array['Amida, entre otras funciones presentes en la molécula', 'Solo hidrocarburo puro, sin otras funciones', 'Solo un gas noble unido al carbono', 'Ninguna función orgánica reconocida'],
   'El paracetamol tiene un grupo amida en su estructura molecular, además de otras funciones orgánicas.'),
  ('75d0da96-c357-4bca-9b47-6306718f0f12', 'en',
   'The amine functional group is structurally derived from which inorganic compound, by replacing hydrogens with organic groups?',
   array['Ammonia (NH₃)', 'Water (H₂O)', 'Carbon dioxide (CO₂)', 'Sulfuric acid (H₂SO₄)'],
   'Amines are considered derivatives of ammonia, with one or more hydrogens replaced by organic groups.'),
  ('75d0da96-c357-4bca-9b47-6306718f0f12', 'es',
   'La función orgánica amina se deriva estructuralmente de ¿qué compuesto inorgánico, al sustituir hidrógenos por radicales orgánicos?',
   array['Amoníaco (NH₃)', 'Agua (H₂O)', 'Dióxido de carbono (CO₂)', 'Ácido sulfúrico (H₂SO₄)'],
   'Las aminas se consideran derivadas del amoníaco, con uno o más hidrógenos sustituidos por radicales orgánicos.'),
  ('638a4c82-66fa-47d0-b47a-6ac749b63fea', 'en',
   'Amines are classified as primary, secondary or tertiary according to:',
   array['The number of organic groups directly bonded to the nitrogen atom', 'The total number of carbon atoms in the molecule', 'The physical state of the compound', 'The presence of aromatic rings, exclusively'],
   'The classification depends on how many hydrogens of the original ammonia were replaced by organic groups.'),
  ('638a4c82-66fa-47d0-b47a-6ac749b63fea', 'es',
   'Las aminas se clasifican en primarias, secundarias o terciarias según:',
   array['El número de radicales orgánicos unidos directamente al átomo de nitrógeno', 'El número total de átomos de carbono de la molécula', 'El estado físico del compuesto', 'La presencia de anillos aromáticos, exclusivamente'],
   'La clasificación depende de cuántos hidrógenos del amoníaco original fueron sustituidos por radicales orgánicos.'),
  ('245e5fb7-c5e9-4fa8-b916-d829ea58347e', 'en',
   'Many amines are known for having characteristic odors, often associated with:',
   array['Rotting fish', 'Fresh, sweet fruit', 'No odor at all', 'Soft floral perfumes, exclusively'],
   'Many short-chain amines have unpleasant odors, reminiscent of rotting fish.'),
  ('245e5fb7-c5e9-4fa8-b916-d829ea58347e', 'es',
   'Muchas aminas son conocidas por tener olores característicos, frecuentemente asociados a:',
   array['Pescado en descomposición', 'Frutas frescas y dulces', 'La ausencia total de olor', 'Perfumes florales suaves, exclusivamente'],
   'Muchas aminas de cadena corta tienen olores desagradables que recuerdan al pescado en descomposición.'),
  ('fc33c557-7d6f-42df-b869-faf16d1eea89', 'en',
   'Amines are basic because of the presence of:',
   array['A lone (unshared) pair of electrons on the nitrogen atom', 'A carboxyl group in their structure', 'A permanent positive electric charge', 'No characteristic related to nitrogen'],
   'The lone pair of electrons on the nitrogen allows amines to act as bases, accepting protons (H⁺).'),
  ('fc33c557-7d6f-42df-b869-faf16d1eea89', 'es',
   'Las aminas tienen carácter básico debido a la presencia de:',
   array['Un par de electrones no compartido en el átomo de nitrógeno', 'Un grupo carboxilo en su estructura', 'Una carga eléctrica positiva permanente', 'Ninguna característica relacionada con el nitrógeno'],
   'El par de electrones libre del nitrógeno permite que las aminas actúen como bases, aceptando protones (H⁺).'),
  ('1a83d3b0-61e4-41f4-9d44-4ffae722d3d7', 'en',
   'Histamine, a biologically important amine, is directly related to:',
   array['Allergic and inflammatory reactions in the body', 'Exclusively digestive processes, with no other function', 'Skin color', 'Muscle energy production'],
   'Histamine is released by the body during allergic and inflammatory reactions and is the target of antihistamines.'),
  ('1a83d3b0-61e4-41f4-9d44-4ffae722d3d7', 'es',
   'La histamina, una amina biológicamente importante, está directamente relacionada con:',
   array['Las reacciones alérgicas e inflamatorias del organismo', 'Procesos exclusivamente digestivos, sin otra función', 'La formación del color de la piel', 'La producción de energía muscular'],
   'El organismo libera histamina durante las reacciones alérgicas e inflamatorias, y es el blanco de los antihistamínicos.'),
  ('ceb7c4f5-be76-4155-b50d-a7a6ba8978f9', 'en',
   'The ketone functional group is characterized by a carbonyl group (C=O) bonded to:',
   array['Two organic groups (carbons), never at the end of the chain', 'A hydrogen atom, necessarily', 'A hydroxyl group', 'A nitrogen atom'],
   'Unlike in an aldehyde, in a ketone the carbonyl is always between two carbons, never at the end of the chain.'),
  ('ceb7c4f5-be76-4155-b50d-a7a6ba8978f9', 'es',
   'La función orgánica cetona se caracteriza por la presencia del grupo carbonilo (C=O) unido a:',
   array['Dos radicales orgánicos (carbonos), nunca en el extremo de la cadena', 'Un átomo de hidrógeno, obligatoriamente', 'Un grupo hidroxilo', 'Un átomo de nitrógeno'],
   'A diferencia del aldehído, en la cetona el carbonilo está siempre entre dos carbonos, nunca en el extremo de la cadena.'),
  ('c003a41c-5a32-47bc-bc72-889a1a11e45f', 'en',
   'Acetone (propanone), the simplest and best-known ketone, is commonly used as:',
   array['A solvent, including in nail polish removers', 'A food preservative', 'Aviation fuel', 'An artificial sweetener'],
   'Acetone is a common solvent, found, for example, in nail polish removers.'),
  ('c003a41c-5a32-47bc-bc72-889a1a11e45f', 'es',
   'La acetona (propanona), la cetona más simple y conocida, se usa comúnmente como:',
   array['Disolvente, incluso en los quitaesmaltes', 'Conservante alimentario', 'Combustible de aviación', 'Edulcorante artificial'],
   'La acetona es un disolvente común, presente, por ejemplo, en los quitaesmaltes de uñas.'),
  ('df5d314f-6570-4484-8d95-15f963b1edc3', 'en',
   'Unlike aldehydes, ketones generally:',
   array['Are not easily oxidized by mild reagents, such as Tollens'' reagent', 'Are always more reactive than aldehydes', 'Cannot be synthesized from secondary alcohols', 'Have hydrogen directly bonded to the carbonyl'],
   'The absence of hydrogen directly bonded to the carbonyl makes ketones more resistant to oxidation than aldehydes.'),
  ('df5d314f-6570-4484-8d95-15f963b1edc3', 'es',
   'A diferencia de los aldehídos, las cetonas generalmente:',
   array['No se oxidan fácilmente con reactivos suaves, como el de Tollens', 'Son siempre más reactivas que los aldehídos', 'No pueden sintetizarse a partir de alcoholes secundarios', 'Tienen hidrógeno unido directamente al carbonilo'],
   'La ausencia de hidrógeno unido directamente al carbonilo hace que las cetonas sean más resistentes a la oxidación que los aldehídos.'),
  ('daf20047-3de3-4817-92e2-69dc32ae6deb', 'en',
   'Ketones can be obtained, among other ways, by the oxidation of:',
   array['Secondary alcohols', 'Primary alcohols, exclusively', 'Saturated hydrocarbons, with no other reagent', 'Noble gases'],
   'The controlled oxidation of a secondary alcohol produces a ketone, while that of a primary alcohol tends to form an aldehyde.'),
  ('daf20047-3de3-4817-92e2-69dc32ae6deb', 'es',
   'Las cetonas pueden obtenerse, entre otras formas, por la oxidación de:',
   array['Alcoholes secundarios', 'Alcoholes primarios, exclusivamente', 'Hidrocarburos saturados, sin ningún otro reactivo', 'Gases nobles'],
   'La oxidación controlada de un alcohol secundario produce una cetona, mientras que la de un alcohol primario tiende a formar un aldehído.'),
  ('584e2071-47ef-421a-b57e-18e09c969cf2', 'en',
   'High levels of ketone bodies in the body, a condition called ketosis, may be associated with:',
   array['Prolonged fasting, low-carbohydrate diets or uncontrolled diabetes', 'Drinking too much water', 'Excessive exposure to sunlight', 'A diet made up exclusively of carbohydrates'],
   'Ketosis occurs when the body starts using fat as its main energy source, producing ketone bodies.'),
  ('584e2071-47ef-421a-b57e-18e09c969cf2', 'es',
   'Los niveles elevados de cuerpos cetónicos en el organismo, condición llamada cetosis, pueden estar asociados a:',
   array['El ayuno prolongado, las dietas bajas en carbohidratos o la diabetes descompensada', 'El consumo excesivo de agua', 'La exposición excesiva a la luz solar', 'Una dieta rica exclusivamente en carbohidratos'],
   'La cetosis ocurre cuando el cuerpo pasa a usar la grasa como principal fuente de energía, produciendo cuerpos cetónicos.'),
  ('55b4da03-c467-4869-b169-50ed66adb34e', 'en',
   'The phenol functional group is characterized by a hydroxyl group (-OH) bonded directly to:',
   array['A carbon of an aromatic ring', 'A saturated carbon, outside any ring', 'A nitrogen atom', 'An oxygen atom of another hydroxyl'],
   'In a phenol, unlike in an alcohol, the hydroxyl is bonded directly to a carbon of the aromatic ring.'),
  ('55b4da03-c467-4869-b169-50ed66adb34e', 'es',
   'La función orgánica fenol se caracteriza por la presencia del grupo hidroxilo (-OH) unido directamente a:',
   array['Un carbono de un anillo aromático', 'Un carbono saturado, fuera de cualquier anillo', 'Un átomo de nitrógeno', 'Un átomo de oxígeno de otro hidroxilo'],
   'En el fenol, a diferencia del alcohol, el hidroxilo está unido directamente a un carbono del anillo aromático.'),
  ('352080a8-b383-4e38-8421-3a52af3e2a5e', 'en',
   'One of the main differences between phenols and alcohols is that phenols are generally:',
   array['More acidic', 'Less acidic', 'Not acidic at all', 'No different from alcohols in any relevant way'],
   'Phenols are more acidic than alcohols, because the phenoxide anion is stabilized by resonance in the aromatic ring.'),
  ('352080a8-b383-4e38-8421-3a52af3e2a5e', 'es',
   'Una de las principales diferencias entre fenoles y alcoholes es que los fenoles tienen, en general:',
   array['Mayor carácter ácido', 'Menor carácter ácido', 'Ausencia total de acidez', 'Ninguna diferencia relevante respecto a los alcoholes'],
   'Los fenoles son más ácidos que los alcoholes, debido a la estabilización del anión fenóxido por la resonancia del anillo aromático.'),
  ('85bba264-6b38-4982-ba0a-ea0760d89ff1', 'en',
   'Ordinary phenol (C₆H₅OH) is historically known for its use, in the 19th century, as:',
   array['One of the first antiseptics used in surgery', 'An artificial sweetener', 'A car fuel', 'A gas used for lighting'],
   'Phenol was one of the first compounds used as an antiseptic, introduced by Joseph Lister into surgical practice.'),
  ('85bba264-6b38-4982-ba0a-ea0760d89ff1', 'es',
   'El fenol común (C₆H₅OH) es conocido históricamente por su uso, en el siglo XIX, como:',
   array['Uno de los primeros antisépticos usados en cirugía', 'Un edulcorante artificial', 'Un combustible para autos', 'Un gas usado en iluminación'],
   'El fenol fue uno de los primeros compuestos usados como antiséptico, introducido por Joseph Lister en la práctica quirúrgica.'),
  ('bf16e722-c07c-4b1d-b160-dcd942d95824', 'en',
   'Phenolic compounds are naturally present in many foods and plants and are associated with properties that are:',
   array['Antioxidant', 'Exclusively toxic, with no benefit', 'Radioactive', 'Metallic'],
   'Many natural phenolic compounds, found in fruits, teas and wines, have antioxidant properties.'),
  ('bf16e722-c07c-4b1d-b160-dcd942d95824', 'es',
   'Los compuestos fenólicos están presentes de forma natural en diversos alimentos y plantas y se asocian a propiedades:',
   array['Antioxidantes', 'Exclusivamente tóxicas, sin ningún beneficio', 'Radiactivas', 'Metálicas'],
   'Muchos compuestos fenólicos naturales, presentes en frutas, tés y vinos, tienen propiedades antioxidantes.'),
  ('829cc26c-4231-46ed-a74e-60c5711f3def', 'en',
   'Unlike alcohols, phenols should not be named with the suffix "-ol" attached to an alkane name, because:',
   array['Their structure is fundamentally tied to an aromatic ring, with its own nomenclature', 'They have no hydroxyl group in their structure', 'They are always gaseous at room temperature', 'They cannot be synthesized in the laboratory'],
   'The presence of the aromatic ring gives phenols a nomenclature and classification different from ordinary alcohols.'),
  ('829cc26c-4231-46ed-a74e-60c5711f3def', 'es',
   'A diferencia de los alcoholes, los fenoles no deben nombrarse con el sufijo "-ol" asociado a un alcano, porque:',
   array['Su estructura está ligada fundamentalmente a un anillo aromático, con nomenclatura propia', 'No tienen ningún grupo hidroxilo en su estructura', 'Son siempre gaseosos a temperatura ambiente', 'No pueden sintetizarse en el laboratorio'],
   'La presencia del anillo aromático hace que los fenoles tengan una nomenclatura y una clasificación distintas de las de los alcoholes comunes.'),
  ('940100d1-a6ad-4b70-a28e-d2bc33492033', 'en',
   'Hydrocarbons are organic compounds made exclusively of atoms of:',
   array['Carbon and hydrogen', 'Carbon and oxygen', 'Carbon and nitrogen', 'Hydrogen and oxygen'],
   'By definition, hydrocarbons contain only carbon and hydrogen.'),
  ('940100d1-a6ad-4b70-a28e-d2bc33492033', 'es',
   'Los hidrocarburos son compuestos orgánicos formados exclusivamente por átomos de:',
   array['Carbono e hidrógeno', 'Carbono y oxígeno', 'Carbono y nitrógeno', 'Hidrógeno y oxígeno'],
   'Por definición, los hidrocarburos contienen solo carbono e hidrógeno en su composición.'),
  ('d68806e4-e684-4031-a92b-8cac9516fe71', 'en',
   'Saturated hydrocarbons, with only single bonds between carbons, are called:',
   array['Alkanes', 'Alkenes', 'Alkynes', 'Aromatics'],
   'Alkanes are saturated hydrocarbons, with the general formula CₙH₂ₙ₊₂.'),
  ('d68806e4-e684-4031-a92b-8cac9516fe71', 'es',
   'Los hidrocarburos saturados, con solo enlaces simples entre carbonos, se llaman:',
   array['Alcanos', 'Alquenos', 'Alquinos', 'Aromáticos'],
   'Los alcanos son hidrocarburos saturados, con fórmula general CₙH₂ₙ₊₂.'),
  ('bf5695f4-bd08-4d76-99a0-e82d5591d70c', 'en',
   'Methane (CH₄), the main component of natural gas, is classified as:',
   array['An alkane', 'An alkene', 'An alcohol', 'A carboxylic acid'],
   'Methane is the simplest alkane, made of a single carbon atom bonded to four hydrogens.'),
  ('bf5695f4-bd08-4d76-99a0-e82d5591d70c', 'es',
   'El metano (CH₄), principal componente del gas natural, se clasifica como:',
   array['Un alcano', 'Un alqueno', 'Un alcohol', 'Un ácido carboxílico'],
   'El metano es el alcano más simple, formado por un único átomo de carbono unido a cuatro hidrógenos.'),
  ('aa5c187d-7d66-42de-8e4d-fdf97d753551', 'en',
   'Benzene (C₆H₆), the fundamental structure of aromatic compounds, is characterized by having:',
   array['A ring of six carbons with alternating bonds (resonance)', 'An open, saturated chain', 'Only triple bonds between the carbons', 'No carbon atoms in its structure'],
   'Benzene has a characteristic hexagonal ring, with bonds that show resonance properties.'),
  ('aa5c187d-7d66-42de-8e4d-fdf97d753551', 'es',
   'El benceno (C₆H₆), estructura fundamental de los compuestos aromáticos, se caracteriza por tener:',
   array['Un anillo de seis carbonos con enlaces alternados (resonancia)', 'Una cadena abierta y saturada', 'Solo enlaces triples entre los carbonos', 'Ningún átomo de carbono en su estructura'],
   'El benceno tiene un anillo hexagonal característico, con enlaces que presentan propiedades de resonancia.'),
  ('4e867929-d531-404f-81c6-adfad8b91ec0', 'en',
   'Hydrocarbons are widely used as an energy source, forming the basis of fuels such as:',
   array['Gasoline, diesel and natural gas', 'Water and table salt', 'Vinegar and cooking alcohol', 'Only radioactive materials'],
   'Most of the fossil fuels used today are made essentially of hydrocarbons.'),
  ('4e867929-d531-404f-81c6-adfad8b91ec0', 'es',
   'Los hidrocarburos se usan ampliamente como fuente de energía y son la base de combustibles como:',
   array['La gasolina, el diésel y el gas natural', 'El agua y la sal de mesa', 'El vinagre y el alcohol de cocina', 'Solo materiales radiactivos'],
   'La mayor parte de los combustibles fósiles que se usan hoy está compuesta esencialmente por hidrocarburos.'),
  ('5762feb9-6d2f-40fc-9572-87cc4671e3f4', 'en',
   'The carboxylic acid functional group is characterized by the presence of the group:',
   array['Carboxyl (-COOH)', 'Hydroxyl (-OH), on its own', 'Carbonyl (C=O), on its own', 'Amine (-NH₂)'],
   'The carboxyl group (-COOH) combines a carbonyl and a hydroxyl on the same carbon, characteristic of carboxylic acids.'),
  ('5762feb9-6d2f-40fc-9572-87cc4671e3f4', 'es',
   'La función orgánica ácido carboxílico se caracteriza por la presencia del grupo funcional:',
   array['Carboxilo (-COOH)', 'Hidroxilo (-OH), aislado', 'Carbonilo (C=O), aislado', 'Amino (-NH₂)'],
   'El carboxilo (-COOH) es la combinación de un carbonilo y un hidroxilo en el mismo carbono, característica de los ácidos carboxílicos.'),
  ('83d3e078-a2bb-4e0c-b654-cd399b56b214', 'en',
   'Acetic acid, found in vinegar, is responsible for its:',
   array['Sour taste and acidity', 'Sweet taste', 'Characteristic color', 'Sweetish smell'],
   'Acetic acid (CH₃COOH) is the main component responsible for the acidity and characteristic taste of vinegar.'),
  ('83d3e078-a2bb-4e0c-b654-cd399b56b214', 'es',
   'El ácido acético, presente en el vinagre, es responsable de su:',
   array['Sabor agrio y carácter ácido', 'Sabor dulce', 'Color característico', 'Olor dulzón'],
   'El ácido acético (CH₃COOH) es el principal componente responsable de la acidez y del sabor característico del vinagre.'),
  ('2c2bdb6b-70fb-4d64-9462-b28305d5996a', 'en',
   'Compared with alcohols with a similar chain, carboxylic acids are:',
   array['More acidic', 'Much less acidic', 'Identically acidic, with no difference', 'Not acidic at all'],
   'The carboxyl group gives carboxylic acids a much more pronounced acidity than that of alcohols.'),
  ('2c2bdb6b-70fb-4d64-9462-b28305d5996a', 'es',
   'En comparación con los alcoholes de cadena semejante, los ácidos carboxílicos tienen un carácter ácido:',
   array['Más acentuado', 'Mucho menos acentuado', 'Idéntico, sin diferencia', 'Nulo, sin ninguna acidez'],
   'El grupo carboxilo confiere a los ácidos carboxílicos un carácter ácido mucho más evidente que el de los alcoholes.'),
  ('42677223-3b5b-4716-8b97-7d5abfdbf33a', 'en',
   'Citric acid, found in fruits such as lemons and oranges, is responsible, among other things, for:',
   array['Giving these fruits their characteristic sour taste', 'Giving the fruits their yellow color', 'Being an alcohol widely used as fuel', 'Having nothing to do with the taste of the fruits'],
   'Citric acid, a natural carboxylic acid, is responsible for the characteristic sour taste of citrus fruits.'),
  ('42677223-3b5b-4716-8b97-7d5abfdbf33a', 'es',
   'El ácido cítrico, presente en frutas como el limón y la naranja, es responsable, entre otros aspectos, de:',
   array['Dar el sabor ácido característico de esas frutas', 'Dar el color amarillo a las frutas', 'Ser un alcohol muy usado como combustible', 'No tener ninguna relación con el sabor de las frutas'],
   'El ácido cítrico, un ácido carboxílico natural, es responsable del sabor agrio característico de los cítricos.'),
  ('4f67a806-da0e-44df-a39d-f52c82038cd7', 'en',
   'Fatty acids, found in oils and fats, are examples of:',
   array['Long-chain carboxylic acids', 'Short-chain alcohols', 'Complex ethers', 'Aromatic amines'],
   'Fatty acids are carboxylic acids with long carbon chains, fundamental components of oils and fats.'),
  ('4f67a806-da0e-44df-a39d-f52c82038cd7', 'es',
   'Los ácidos grasos, presentes en aceites y grasas, son ejemplos de:',
   array['Ácidos carboxílicos de cadena larga', 'Alcoholes de cadena corta', 'Éteres complejos', 'Aminas aromáticas'],
   'Los ácidos grasos son ácidos carboxílicos con largas cadenas carbonadas, componentes fundamentales de aceites y grasas.'),
  ('5dec92fc-0ed3-4c8f-892b-8f74f7bbef75', 'en',
   'The alcohol functional group is characterized by the presence of:',
   array['A hydroxyl group (-OH) bonded to a saturated carbon', 'A carbonyl group (C=O)', 'A carboxyl group (-COOH)', 'An amine group (-NH₂)'],
   'A hydroxyl group (-OH) bonded to a saturated (non-aromatic) carbon characterizes alcohols.'),
  ('5dec92fc-0ed3-4c8f-892b-8f74f7bbef75', 'es',
   'La función orgánica alcohol se caracteriza por la presencia del grupo funcional:',
   array['Hidroxilo (-OH) unido a un carbono saturado', 'Carbonilo (C=O)', 'Carboxilo (-COOH)', 'Amino (-NH₂)'],
   'El grupo hidroxilo (-OH), unido a un carbono saturado (no aromático), caracteriza a los alcoholes.'),
  ('6db914fb-3542-49e3-9862-aadc5b01ef72', 'en',
   'Ethanol (ethyl alcohol), widely used as a fuel and in alcoholic beverages, is obtained industrially, among other ways, by fermenting:',
   array['Sugars, such as those in sugarcane', 'Crude oil exclusively', 'Metal ores', 'Noble gases'],
   'The fermentation of sugars (such as sucrose from sugarcane) by yeast is the main way ethanol is produced in Brazil.'),
  ('6db914fb-3542-49e3-9862-aadc5b01ef72', 'es',
   'El etanol (alcohol etílico), muy usado como combustible y en bebidas alcohólicas, se obtiene industrialmente, entre otras formas, a partir de la fermentación de:',
   array['Azúcares, como los presentes en la caña de azúcar', 'Petróleo crudo exclusivamente', 'Minerales metálicos', 'Gases nobles'],
   'La fermentación de azúcares (como la sacarosa de la caña) por levaduras es el principal proceso de obtención del etanol en Brasil.'),
  ('9bc268fb-222e-4cc0-9279-f5ba1f5caf28', 'en',
   'Alcohols are classified as primary, secondary or tertiary according to:',
   array['The type of carbon the hydroxyl is bonded to', 'The total number of carbon atoms in the molecule', 'The physical state of the compound', 'The presence or absence of rings in the structure'],
   'The classification depends on whether the hydroxyl is bonded to a primary, secondary or tertiary carbon.'),
  ('9bc268fb-222e-4cc0-9279-f5ba1f5caf28', 'es',
   'Los alcoholes se clasifican en primarios, secundarios o terciarios según:',
   array['El tipo de carbono al que está unido el hidroxilo', 'El número total de átomos de carbono de la molécula', 'El estado físico del compuesto', 'La presencia o ausencia de anillos en la estructura'],
   'La clasificación depende de si el hidroxilo está unido a un carbono primario, secundario o terciario.'),
  ('2aa86aef-e8af-49c6-9f17-254959909981', 'en',
   'Unlike ethanol, methanol is a substance that is:',
   array['Highly toxic to humans, capable of causing blindness and death', 'Safe for human consumption in any amount', 'Chemically identical to ethanol', 'Used exclusively as a sweetener'],
   'Methanol is toxic even in small amounts and can seriously damage vision and the nervous system.'),
  ('2aa86aef-e8af-49c6-9f17-254959909981', 'es',
   'A diferencia del etanol, el metanol es una sustancia:',
   array['Muy tóxica para el ser humano, que puede causar ceguera y muerte', 'Segura para el consumo humano en cualquier cantidad', 'Químicamente idéntica al etanol', 'Usada exclusivamente como edulcorante'],
   'El metanol es tóxico incluso en pequeñas cantidades y puede causar daños graves a la visión y al sistema nervioso.'),
  ('fa64dbd9-bda4-4f20-8f19-06d2af5ee6d2', 'en',
   'Glycerol (glycerin), an alcohol with three hydroxyl groups (a triol), is widely used in:',
   array['Cosmetics and hygiene products, for its moisturizing properties', 'Car fuels exclusively', 'Glassmaking', 'Producing noble gases'],
   'Glycerol is valued for its ability to retain moisture and is widely used in creams and soaps.'),
  ('fa64dbd9-bda4-4f20-8f19-06d2af5ee6d2', 'es',
   'El glicerol (glicerina), un alcohol con tres hidroxilos (trialcohol), se usa ampliamente en:',
   array['Cosméticos y productos de higiene, por sus propiedades hidratantes', 'Combustibles para autos exclusivamente', 'La fabricación de vidrio', 'La producción de gases nobles'],
   'El glicerol se valora por su capacidad de retener humedad y se usa mucho en cremas y jabones.'),
  ('4b16fc5c-380e-4aee-8cc7-5263376d548f', 'en',
   'The ester functional group is formed mainly from the reaction between:',
   array['A carboxylic acid and an alcohol, releasing water', 'Two different alcohols', 'An ether and an amine', 'A hydrocarbon and a noble gas'],
   'The esterification reaction combines a carboxylic acid and an alcohol, forming an ester and water.'),
  ('4b16fc5c-380e-4aee-8cc7-5263376d548f', 'es',
   'La función orgánica éster se forma, principalmente, a partir de la reacción entre:',
   array['Un ácido carboxílico y un alcohol, con liberación de agua', 'Dos alcoholes diferentes', 'Un éter y una amina', 'Un hidrocarburo y un gas noble'],
   'La reacción de esterificación combina un ácido carboxílico y un alcohol y forma un éster y agua.'),
  ('4fae92b7-1c62-4aa0-8630-d3d2c968a835', 'en',
   'Many esters are known for having:',
   array['Pleasant odors, often associated with fruit', 'Extremely unpleasant odors, without exception', 'No odor at all', 'A characteristic reddish color'],
   'Many natural esters are responsible for the characteristic aromas of fruits and are also used in perfumery.'),
  ('4fae92b7-1c62-4aa0-8630-d3d2c968a835', 'es',
   'Muchos ésteres son conocidos por tener:',
   array['Olores agradables, frecuentemente asociados a frutas', 'Olores extremadamente desagradables, sin excepción', 'Ausencia total de olor', 'Un color rojizo característico'],
   'Diversos ésteres naturales son responsables de los aromas característicos de las frutas y se usan también en perfumería.'),
  ('d5ac2dbe-fcb4-4b1d-a6e8-bf04df86af76', 'en',
   'Chemically, fats and vegetable oils are made mainly of:',
   array['Esters of fatty acids with glycerol (triglycerides)', 'Simple short-chain ethers', 'Long-chain amines', 'Aromatic hydrocarbons'],
   'Triglycerides, found in fats and oils, are esters formed by combining glycerol with three fatty acids.'),
  ('d5ac2dbe-fcb4-4b1d-a6e8-bf04df86af76', 'es',
   'Químicamente, las grasas y los aceites vegetales están formados principalmente por:',
   array['Ésteres de ácidos grasos con glicerol (triglicéridos)', 'Éteres simples de cadena corta', 'Aminas de cadena larga', 'Hidrocarburos aromáticos'],
   'Los triglicéridos, presentes en grasas y aceites, son ésteres formados por la combinación de glicerol con tres ácidos grasos.'),
  ('ccd0e4b0-25a5-4124-a405-00e9f6f093ba', 'en',
   'The reverse of esterification, which breaks an ester down into a carboxylic acid and an alcohol in the presence of water, is called:',
   array['Hydrolysis', 'Oxidation', 'Halogenation', 'Nitration'],
   'Hydrolysis of the ester, in the presence of water, regenerates the original carboxylic acid and alcohol.'),
  ('ccd0e4b0-25a5-4124-a405-00e9f6f093ba', 'es',
   'La reacción inversa a la esterificación, que descompone un éster en ácido carboxílico y alcohol en presencia de agua, se llama:',
   array['Hidrólisis', 'Oxidación', 'Halogenación', 'Nitración'],
   'La hidrólisis del éster, en presencia de agua, regenera el ácido carboxílico y el alcohol originales.'),
  ('e5b98dba-1abc-483a-a794-b7c5904fa970', 'en',
   'Aspartame, a widely used artificial sweetener, is an example of a compound whose structure contains the function:',
   array['Ester, among other functions present', 'Only pure hydrocarbon', 'Only a noble gas bonded to carbon', 'No recognized organic function'],
   'Aspartame is a complex molecule that includes, among its organic functions, an ester group.'),
  ('e5b98dba-1abc-483a-a794-b7c5904fa970', 'es',
   'El aspartamo, un edulcorante artificial muy usado, es un ejemplo de compuesto que contiene en su estructura la función:',
   array['Éster, entre otras funciones presentes', 'Solo hidrocarburo puro', 'Solo un gas noble unido al carbono', 'Ninguna función orgánica reconocida'],
   'El aspartamo es una molécula compleja que incluye, entre sus funciones orgánicas, un grupo éster.'),
  ('ab25822f-0b7c-49c9-8df0-3c98b7da907b', 'en',
   'The ether functional group is characterized by an oxygen atom:',
   array['Bonded to two organic groups (carbons), with no hydrogen directly bonded to it', 'Bonded to a single carbon atom and a hydrogen', 'Bonded to a nitrogen atom', 'Forming a double bond with carbon'],
   'In ethers, the oxygen acts as a "bridge" between two organic groups, with no hydrogen directly bonded to it.'),
  ('ab25822f-0b7c-49c9-8df0-3c98b7da907b', 'es',
   'La función orgánica éter se caracteriza por la presencia de un átomo de oxígeno:',
   array['Unido a dos grupos orgánicos (carbonos), sin hidrógeno unido directamente a él', 'Unido a un único átomo de carbono y a un hidrógeno', 'Unido a un átomo de nitrógeno', 'Que forma un doble enlace con el carbono'],
   'En los éteres, el oxígeno actúa como un "puente" entre dos grupos orgánicos, sin hidrógeno unido directamente a él.'),
  ('4fa3d27f-d5df-48e7-a3c8-d3b4e87b88b9', 'en',
   'Ethyl (diethyl) ether was historically used in medicine as:',
   array['One of the first general anesthetics', 'An antibiotic', 'A topical painkiller only', 'An artificial sweetener'],
   'Diethyl ether was widely used as a general anesthetic in surgery, especially in the 19th and early 20th centuries.'),
  ('4fa3d27f-d5df-48e7-a3c8-d3b4e87b88b9', 'es',
   'El éter etílico (dietílico) se usó históricamente en medicina como:',
   array['Uno de los primeros anestésicos generales', 'Un antibiótico', 'Un analgésico tópico solamente', 'Un edulcorante artificial'],
   'El éter dietílico se usó ampliamente como anestésico general en cirugías, sobre todo en el siglo XIX y a principios del XX.'),
  ('84cd6fd2-6c70-40b5-8a7d-d25ac10b01bd', 'en',
   'Ethers are generally considered compounds with low chemical reactivity, mainly because they:',
   array['Have no hydrogen directly bonded to the oxygen', 'Are extremely unstable', 'Carry a high electric charge', 'React spontaneously with any substance'],
   'The absence of hydrogen bonded to the oxygen reduces their ability to form strong hydrogen bonds, which makes ethers not very reactive.'),
  ('84cd6fd2-6c70-40b5-8a7d-d25ac10b01bd', 'es',
   'Los éteres se consideran generalmente compuestos de baja reactividad química, principalmente por:',
   array['No tener hidrógeno unido directamente al oxígeno', 'Ser extremadamente inestables', 'Tener una carga eléctrica elevada', 'Reaccionar espontáneamente con cualquier sustancia'],
   'La ausencia de hidrógeno unido al oxígeno reduce la capacidad de formar puentes de hidrógeno intensos, lo que hace que los éteres sean poco reactivos.'),
  ('012d643c-5981-495c-81e9-1bfee34bd83f', 'en',
   'An ether and an alcohol can have the same molecular formula, in which case they are considered:',
   array['Functional isomers', 'Isotopes', 'Identical substances', 'Allotropes'],
   'Dimethyl ether and ethyl alcohol, for example, share the formula C₂H₆O but belong to different organic functions.'),
  ('012d643c-5981-495c-81e9-1bfee34bd83f', 'es',
   'Un éter y un alcohol pueden tener la misma fórmula molecular, y en ese caso se consideran:',
   array['Isómeros de función', 'Isótopos', 'Sustancias idénticas', 'Alótropos'],
   'El éter dimetílico y el alcohol etílico, por ejemplo, comparten la fórmula C₂H₆O, pero pertenecen a funciones orgánicas diferentes.'),
  ('0dfb31cc-6450-4752-a7cc-b568069ea9b7', 'en',
   'Ethers are often used as solvents in chemistry laboratories because of:',
   array['Their low reactivity and good ability to dissolve organic compounds', 'Their high reactivity with almost every substance', 'Their inability to dissolve any substance', 'Their extreme toxicity, which prevents any handling'],
   'The low reactivity of ethers makes them useful solvents, although they require care because they are flammable.'),
  ('0dfb31cc-6450-4752-a7cc-b568069ea9b7', 'es',
   'Los éteres se usan con frecuencia como disolventes en los laboratorios de química debido a:',
   array['Su baja reactividad y su buena capacidad para disolver compuestos orgánicos', 'Su alta reactividad con casi todas las sustancias', 'Su incapacidad para disolver cualquier sustancia', 'Su toxicidad extrema, que impide cualquier manipulación'],
   'La baja reactividad de los éteres los convierte en disolventes útiles, aunque exigen cuidado por ser inflamables.'),
  ('1964980c-beea-4abd-85f2-d776da0d4b84', 'en',
   'Isomers are compounds that have:',
   array['The same molecular formula but different structures (structural formulas)', 'Different molecular formulas and the same structure', 'The same molecular formula and the same structure, with no difference', 'No similarity between their formulas'],
   'Isomers share the same molecular formula but differ in how the atoms are arranged in the structure.'),
  ('1964980c-beea-4abd-85f2-d776da0d4b84', 'es',
   'Los isómeros son compuestos que tienen:',
   array['La misma fórmula molecular, pero estructuras (fórmulas estructurales) diferentes', 'Fórmulas moleculares diferentes y la misma estructura', 'La misma fórmula molecular y la misma estructura, sin ninguna diferencia', 'Ninguna semejanza entre sus fórmulas'],
   'Los isómeros comparten la misma fórmula molecular, pero difieren en la forma en que se organizan los átomos en la estructura.'),
  ('af423cbc-3b98-4ebd-9d04-5fd67874a190', 'en',
   'In chain isomerism, the isomers differ in:',
   array['The type of carbon chain (open, closed, branched, straight)', 'The position of a heteroatom only', 'The organic function present in the molecule', 'The spatial arrangement of atoms, without changing the chain'],
   'In chain isomerism, the compounds have the same organic function but structurally different carbon chains.'),
  ('af423cbc-3b98-4ebd-9d04-5fd67874a190', 'es',
   'En la isomería de cadena, los isómeros difieren en:',
   array['El tipo de cadena carbonada (abierta, cerrada, ramificada, normal)', 'La posición de un heteroátomo solamente', 'La función orgánica presente en la molécula', 'La disposición espacial de los átomos, sin alterar la cadena'],
   'En la isomería de cadena, los compuestos tienen la misma función orgánica, pero cadenas carbonadas estructuralmente diferentes.'),
  ('3d5bbdc8-3665-4159-b007-1107f057af07', 'en',
   'In functional isomerism, the isomers belong to:',
   array['Different organic functions, despite having the same molecular formula', 'Always the same organic function', 'Different chemical elements', 'Different physical states, exclusively'],
   'A classic example is ethyl alcohol and dimethyl ether, both with the formula C₂H₆O, but with different organic functions.'),
  ('3d5bbdc8-3665-4159-b007-1107f057af07', 'es',
   'En la isomería de función, los isómeros pertenecen a:',
   array['Funciones orgánicas diferentes, aunque tengan la misma fórmula molecular', 'Siempre la misma función orgánica', 'Elementos químicos diferentes', 'Estados físicos diferentes, exclusivamente'],
   'Un ejemplo clásico es el alcohol etílico y el éter dimetílico, ambos con fórmula C₂H₆O, pero de funciones orgánicas distintas.'),
  ('ffd7e349-d889-41d6-a2de-723a552c3b2c', 'en',
   'Geometric (cis-trans) isomerism occurs in compounds that have:',
   array['Restricted free rotation, usually due to a double bond or a ring', 'Only single bonds, with no rotation restriction', 'No carbon in their structure at all', 'Always open, saturated chains'],
   'Cis-trans isomerism depends on restricted rotation around a double bond (or a cyclic structure).'),
  ('ffd7e349-d889-41d6-a2de-723a552c3b2c', 'es',
   'La isomería geométrica (cis-trans) ocurre en compuestos que tienen:',
   array['Restricción a la libre rotación, generalmente debido a un doble enlace o a un anillo', 'Solo enlaces simples, sin ninguna restricción de rotación', 'Ausencia total de carbono en la estructura', 'Siempre cadenas abiertas y saturadas'],
   'La isomería cis-trans depende de la restricción de rotación en torno a un doble enlace (o a una estructura cíclica).'),
  ('13da8b1d-521d-42a7-804f-4dabf8fe2037', 'en',
   'Optical isomerism is related to the presence of:',
   array['A chiral (asymmetric) carbon, bonded to four different groups', 'A double bond between carbons', 'An aromatic ring in the molecule', 'Only hydrogen atoms in the chain'],
   'The chiral carbon, bonded to four different substituents, is the basis of optical isomerism.'),
  ('13da8b1d-521d-42a7-804f-4dabf8fe2037', 'es',
   'La isomería óptica está relacionada con la presencia de:',
   array['Un carbono quiral (asimétrico), unido a cuatro grupos diferentes', 'Un doble enlace entre carbonos', 'Un anillo aromático en la molécula', 'Solo átomos de hidrógeno en la cadena'],
   'El carbono quiral, unido a cuatro sustituyentes diferentes, es la base de la isomería óptica.'),
  ('c66818f6-142f-4801-95f6-74f9e58ccd7f', 'en',
   'According to IUPAC rules, the name of a straight-chain saturated hydrocarbon (alkane) with 4 carbon atoms is:',
   array['Butane', 'Propane', 'Pentane', 'Methane'],
   'Alkane names use prefixes according to the number of carbons: but (4) + ane.'),
  ('c66818f6-142f-4801-95f6-74f9e58ccd7f', 'es',
   'Según las reglas de la IUPAC, el nombre de un hidrocarburo saturado (alcano) de cadena normal con 4 átomos de carbono es:',
   array['Butano', 'Propano', 'Pentano', 'Metano'],
   'La nomenclatura de los alcanos sigue prefijos según el número de carbonos: but (4) + ano.'),
  ('291027e0-8329-4cc1-bace-92db7f7d6ec1', 'en',
   'The prefix "meth-", used in organic nomenclature, indicates a main chain with how many carbon atoms?',
   array['1', '2', '3', '4'],
   'The prefix "meth-" corresponds to just 1 carbon atom in the main chain, as in methane (CH₄).'),
  ('291027e0-8329-4cc1-bace-92db7f7d6ec1', 'es',
   'El prefijo "met-", usado en la nomenclatura orgánica, indica una cadena principal con ¿cuántos átomos de carbono?',
   array['1', '2', '3', '4'],
   'El prefijo "met-" corresponde a solo 1 átomo de carbono en la cadena principal, como en el metano (CH₄).'),
  ('7ef545ce-844c-47fe-9f5f-fcba3e9a9e4f', 'en',
   'In organic nomenclature, the suffix "-ol" indicates the presence of which function?',
   array['Alcohol', 'Carboxylic acid', 'Ketone', 'Amine'],
   'The suffix "-ol" is characteristic of alcohols, indicating a hydroxyl group (-OH) bonded to a saturated carbon.'),
  ('7ef545ce-844c-47fe-9f5f-fcba3e9a9e4f', 'es',
   'En la nomenclatura orgánica, el sufijo "-ol" indica la presencia de la función:',
   array['Alcohol', 'Ácido carboxílico', 'Cetona', 'Amina'],
   'El sufijo "-ol" es característico de los alcoholes e indica la presencia del grupo hidroxilo (-OH) unido a un carbono saturado.'),
  ('756a1cc2-dc59-4c8d-bb9b-6ea7a5184562', 'en',
   'In naming an alkene (a hydrocarbon with a double bond), the suffix used is:',
   array['-ene', '-ane', '-yne', '-ol'],
   'The suffix "-ene" indicates a double bond between carbons, as in ethene (CH₂=CH₂).'),
  ('756a1cc2-dc59-4c8d-bb9b-6ea7a5184562', 'es',
   'En la nomenclatura de un alqueno (hidrocarburo con un doble enlace), el sufijo que se usa es:',
   array['-eno', '-ano', '-ino', '-ol'],
   'El sufijo "-eno" indica la presencia de un doble enlace entre carbonos, como en el eteno (CH₂=CH₂).'),
  ('7ab39b95-f878-4ac5-8457-fb79a56cfb8f', 'en',
   'In organic nomenclature, numerical prefixes (such as di-, tri-, tetra-) are used to indicate:',
   array['How many times a given group or branch is repeated in the molecule', 'Always the total number of carbon atoms in the molecule', 'Only the number of hydrogen atoms', 'The molecular mass of the compound'],
   'Prefixes such as di-, tri- and tetra- indicate how many times the same group or branch appears in the structure.'),
  ('7ab39b95-f878-4ac5-8457-fb79a56cfb8f', 'es',
   'En la nomenclatura orgánica, los prefijos numéricos (como di-, tri-, tetra-) se usan para indicar:',
   array['La cantidad de veces que un grupo o ramificación se repite en la molécula', 'Siempre el número total de átomos de carbono de la molécula', 'Solo el número de átomos de hidrógeno', 'La masa molecular del compuesto'],
   'Prefijos como di-, tri- y tetra- indican cuántas veces aparece un mismo grupo o ramificación en la estructura.'),
  ('39fa0c38-1531-4430-b57d-07f901d2f2f4', 'en',
   'Polymers are macromolecules formed by the repetition of smaller structural units called:',
   array['Monomers', 'Isomers', 'Catalysts', 'Free radicals'],
   'Polymers result from the repeated linking of basic units (monomers) through polymerization reactions.'),
  ('39fa0c38-1531-4430-b57d-07f901d2f2f4', 'es',
   'Los polímeros son macromoléculas formadas por la repetición de unidades estructurales más pequeñas llamadas:',
   array['Monómeros', 'Isómeros', 'Catalizadores', 'Radicales libres'],
   'Los polímeros resultan de la unión repetida de unidades básicas (monómeros) mediante reacciones de polimerización.'),
  ('a58f9fac-aeb6-437c-87d7-0d4b67a4d3d8', 'en',
   'Polyethylene, one of the most common plastics, is formed by polymerizing the monomer:',
   array['Ethene (ethylene)', 'Methane', 'Acetic acid', 'Benzene'],
   'Polyethylene is formed by the repeated addition of ethene molecules (CH₂=CH₂).'),
  ('a58f9fac-aeb6-437c-87d7-0d4b67a4d3d8', 'es',
   'El polietileno, uno de los plásticos más comunes, se forma por la polimerización del monómero:',
   array['Eteno (etileno)', 'Metano', 'Ácido acético', 'Benceno'],
   'El polietileno se forma por la adición repetida de moléculas de eteno (CH₂=CH₂).'),
  ('e8ed8d21-cb34-4a4d-b4c3-f804f16ab93e', 'en',
   'Unlike synthetic polymers, natural polymers are produced:',
   array['By living organisms, such as cellulose and proteins', 'Exclusively in industrial laboratories', 'Always from petroleum', 'Only by nuclear fusion processes'],
   'Natural polymers, such as cellulose, starch and proteins, are produced by living organisms.'),
  ('e8ed8d21-cb34-4a4d-b4c3-f804f16ab93e', 'es',
   'A diferencia de los sintéticos, los polímeros naturales son producidos:',
   array['Por organismos vivos, como la celulosa y las proteínas', 'Exclusivamente en laboratorios industriales', 'Siempre a partir del petróleo', 'Solo por procesos de fusión nuclear'],
   'Los polímeros naturales, como la celulosa, el almidón y las proteínas, son producidos por organismos vivos.'),
  ('b00e3039-b49d-4596-a12b-91f70b11dce8', 'en',
   'One of the main environmental problems associated with synthetic polymers (conventional plastics) is:',
   array['Their slow rate of natural degradation, staying in the environment for a long time', 'Their rapid decomposition in a few days', 'The impossibility of recycling them', 'A complete absence of environmental impact'],
   'Many conventional plastics take decades or centuries to degrade naturally.'),
  ('b00e3039-b49d-4596-a12b-91f70b11dce8', 'es',
   'Uno de los principales problemas ambientales asociados a los polímeros sintéticos (plásticos convencionales) es:',
   array['Su baja tasa de degradación natural, por la que permanecen mucho tiempo en el ambiente', 'Su rápida descomposición en pocos días', 'La imposibilidad de reciclarlos', 'La ausencia total de impacto ambiental'],
   'Muchos plásticos convencionales tardan décadas o siglos en degradarse de forma natural.'),
  ('54006ef8-6f3a-4509-8a6e-3577442fbf48', 'en',
   'Biodegradable polymers differ from conventional ones in that they can:',
   array['Decompose more quickly through the action of microorganisms', 'Never degrade, even with microbial action', 'Be produced exclusively from metals', 'Completely replace the use of any plastic today'],
   'Biodegradable polymers are designed to be broken down more quickly by microorganisms.'),
  ('54006ef8-6f3a-4509-8a6e-3577442fbf48', 'es',
   'Los polímeros biodegradables se diferencian de los convencionales por ser capaces de:',
   array['Descomponerse más rápido por la acción de microorganismos', 'No degradarse nunca, ni siquiera con acción microbiana', 'Producirse exclusivamente a partir de metales', 'Sustituir por completo el uso de cualquier plástico hoy'],
   'Los polímeros biodegradables están diseñados para ser descompuestos más rápido por microorganismos.'),
  ('3cd231fb-5b54-4c06-ad2e-9d659079b700', 'en',
   'Substitution reactions, common in saturated compounds such as alkanes, consist of:',
   array['Swapping one atom or group in the molecule for another', 'Adding atoms to a double or triple bond', 'Removing atoms, forming a double bond', 'Joining two small molecules into a larger one, with no loss of atoms'],
   'In substitution, an atom (usually hydrogen) is swapped for another atom or group.'),
  ('3cd231fb-5b54-4c06-ad2e-9d659079b700', 'es',
   'Las reacciones de sustitución, comunes en compuestos saturados como los alcanos, consisten en:',
   array['Cambiar un átomo o grupo de la molécula por otro', 'Añadir átomos a un enlace doble o triple', 'Eliminar átomos, formando un doble enlace', 'Unir dos moléculas pequeñas en una mayor, sin pérdida de átomos'],
   'En la sustitución, un átomo (generalmente hidrógeno) se cambia por otro átomo o grupo.'),
  ('5f010b42-7b68-436f-93b8-03bc834a0b65', 'en',
   'Addition reactions, typical of unsaturated compounds such as alkenes, consist of:',
   array['Adding atoms to a double or triple bond, turning it into a single bond', 'Removing atoms from the molecule, forming a double bond', 'Swapping a hydrogen atom for another atom', 'Forming aromatic compounds exclusively'],
   'In addition, atoms bond directly to the carbons of the double (or triple) bond, which becomes a single bond.'),
  ('5f010b42-7b68-436f-93b8-03bc834a0b65', 'es',
   'Las reacciones de adición, típicas de compuestos insaturados como los alquenos, consisten en:',
   array['Añadir átomos a un enlace doble o triple, que se transforma en enlace simple', 'Retirar átomos de la molécula, formando un doble enlace', 'Cambiar un átomo de hidrógeno por otro átomo', 'Formar exclusivamente compuestos aromáticos'],
   'En la adición, los átomos se unen directamente a los carbonos del enlace doble (o triple), que se transforma en enlace simple.'),
  ('d59dba17-8724-4814-9ac3-056d6a236ae8', 'en',
   'Elimination reactions are characterized by:',
   array['Removing atoms from a molecule, usually forming a double or triple bond', 'Adding atoms to a single bond', 'Swapping one atom for another without changing the type of bond', 'Occurring exclusively in aromatic compounds'],
   'Elimination reactions remove atoms from the molecule, creating an unsaturation.'),
  ('d59dba17-8724-4814-9ac3-056d6a236ae8', 'es',
   'Las reacciones de eliminación se caracterizan por:',
   array['Retirar átomos de una molécula, generalmente formando un enlace doble o triple', 'Añadir átomos a un enlace simple', 'Sustituir un átomo por otro sin alterar el tipo de enlace', 'Ocurrir exclusivamente en compuestos aromáticos'],
   'Las reacciones de eliminación retiran átomos de la molécula y generan una insaturación.'),
  ('03de321c-160c-40a3-ade4-a753548df56c', 'en',
   'The complete combustion of a hydrocarbon, with enough oxygen, mainly produces:',
   array['Carbon dioxide (CO₂) and water (H₂O)', 'Only solid carbon (soot)', 'Only hydrogen gas', 'Pure nitrogen and oxygen'],
   'The complete combustion of hydrocarbons, with enough oxygen, produces CO₂ and H₂O as its main products.'),
  ('03de321c-160c-40a3-ade4-a753548df56c', 'es',
   'La combustión completa de un hidrocarburo, en presencia de oxígeno suficiente, produce principalmente:',
   array['Dióxido de carbono (CO₂) y agua (H₂O)', 'Solo carbono sólido (hollín)', 'Solo gas hidrógeno', 'Nitrógeno y oxígeno puros'],
   'La combustión completa de los hidrocarburos, con oxígeno suficiente, genera CO₂ y H₂O como productos principales.'),
  ('6fe6faf5-d368-49a3-9a83-aea18cc32f48', 'en',
   'The esterification reaction, which produces esters, occurs between:',
   array['A carboxylic acid and an alcohol', 'An alkane and an alkene', 'Two carboxylic acids', 'An ether and a ketone'],
   'Esterification combines a carboxylic acid and an alcohol, releasing water and forming an ester.'),
  ('6fe6faf5-d368-49a3-9a83-aea18cc32f48', 'es',
   'La reacción de esterificación, que produce ésteres, ocurre a partir de la reacción entre:',
   array['Un ácido carboxílico y un alcohol', 'Un alcano y un alqueno', 'Dos ácidos carboxílicos', 'Un éter y una cetona'],
   'La esterificación combina un ácido carboxílico y un alcohol, libera agua y forma un éster.'),
  ('18de5487-4b0f-44f9-96b4-dd7d1d337348', 'en',
   'A chemical solution is defined as a mixture that is:',
   array['Homogeneous, of two or more substances', 'Heterogeneous, of two substances', 'Made of a single component exclusively', 'Always in the solid state'],
   'Solutions are homogeneous mixtures, in which the components cannot be told apart visually.'),
  ('18de5487-4b0f-44f9-96b4-dd7d1d337348', 'es',
   'Una solución química se define como una mezcla:',
   array['Homogénea de dos o más sustancias', 'Heterogénea de dos sustancias', 'Formada exclusivamente por un único componente', 'Siempre en estado sólido'],
   'Las soluciones son mezclas homogéneas, en las que no es posible distinguir visualmente los componentes.'),
  ('caa46d82-79de-4e3f-b251-8331a190dec8', 'en',
   'In a solution, the component present in the largest amount is usually called the:',
   array['Solvent', 'Solute', 'Precipitate', 'Catalyst'],
   'The solvent is the component present in the largest proportion, in which the solute dissolves.'),
  ('caa46d82-79de-4e3f-b251-8331a190dec8', 'es',
   'En una solución, el componente presente en mayor cantidad se llama generalmente:',
   array['Disolvente', 'Soluto', 'Precipitado', 'Catalizador'],
   'El disolvente es el componente presente en mayor proporción, en el que se disuelve el soluto.'),
  ('e2ccfafa-0f8d-402d-856a-de50f60f617e', 'en',
   'The mass concentration of a solution is usually expressed as the ratio between:',
   array['The mass of solute and the volume of solution', 'The mass of solvent and the mass of solute', 'The volume of solvent only', 'The number of moles of solvent'],
   'Mass concentration (C) is defined as the mass of solute divided by the total volume of solution, usually in g/L.'),
  ('e2ccfafa-0f8d-402d-856a-de50f60f617e', 'es',
   'La concentración común de una solución se expresa generalmente como la razón entre:',
   array['La masa del soluto y el volumen de la solución', 'La masa del disolvente y la masa del soluto', 'Solo el volumen del disolvente', 'El número de moles del disolvente'],
   'La concentración común (C) se define como la masa del soluto dividida por el volumen total de la solución, generalmente en g/L.'),
  ('ac8d8444-81c5-4ec6-acc2-126acaf2f4a3', 'en',
   'A solution is classified as saturated when it:',
   array['Contains the maximum amount of solute that can dissolve at that temperature', 'Contains less solute than the solvent could dissolve', 'Contains no dissolved solute', 'Is always a heterogeneous solution'],
   'At saturation, the solution reaches the solubility limit of the solute at that temperature.'),
  ('ac8d8444-81c5-4ec6-acc2-126acaf2f4a3', 'es',
   'Una solución se clasifica como saturada cuando:',
   array['Contiene la cantidad máxima de soluto que puede disolverse a esa temperatura', 'Contiene menos soluto del que el disolvente podría disolver', 'No contiene ningún soluto disuelto', 'Es siempre una solución heterogénea'],
   'En la saturación, la solución alcanza el límite de solubilidad del soluto a esa temperatura.'),
  ('7c476ddc-1d04-4f05-8783-e7b86265495a', 'en',
   'When a solution is diluted by adding more solvent without changing the amount of solute, its concentration:',
   array['Decreases', 'Increases', 'Stays the same', 'Becomes undefined'],
   'Since the same amount of solute now occupies a larger volume, the concentration decreases with dilution.'),
  ('7c476ddc-1d04-4f05-8783-e7b86265495a', 'es',
   'Al diluir una solución añadiendo más disolvente sin alterar la cantidad de soluto, la concentración de la solución:',
   array['Disminuye', 'Aumenta', 'Permanece igual', 'Se vuelve indefinida'],
   'Como la misma cantidad de soluto pasa a ocupar un volumen mayor, la concentración disminuye con la dilución.'),
  ('658a27e8-fe5e-4d1c-9bd5-9b5ce05a83a4', 'en',
   'The solubility of a solute in a given solvent can vary according to:',
   array['Temperature and, for gases, pressure', 'Only the color of the solvent', 'No external factor, always staying constant', 'Only the total volume of the solution'],
   'Factors such as temperature and pressure directly influence the solubility of a solute.'),
  ('658a27e8-fe5e-4d1c-9bd5-9b5ce05a83a4', 'es',
   'La solubilidad de un soluto en un disolvente determinado puede variar según:',
   array['La temperatura y, en el caso de los gases, la presión', 'Solo el color del disolvente', 'Ningún factor externo, pues permanece siempre constante', 'Solo el volumen total de la solución'],
   'Factores como la temperatura y la presión influyen directamente en la solubilidad de un soluto.'),
  ('8770435a-cc5c-43ac-86a2-68b550a07f66', 'en',
   'Two solutions are considered isotonic when they have:',
   array['The same concentration of dissolved particles (the same osmotic pressure)', 'Identical colors, regardless of concentration', 'Identical volumes, regardless of concentration', 'Different solvents, necessarily'],
   'Isotonic solutions have the same osmotic pressure, that is, equivalent concentrations of dissolved particles.'),
  ('8770435a-cc5c-43ac-86a2-68b550a07f66', 'es',
   'Dos soluciones se consideran isotónicas cuando tienen:',
   array['La misma concentración de partículas disueltas (la misma presión osmótica)', 'Colores idénticos, independientemente de la concentración', 'Volúmenes idénticos, independientemente de la concentración', 'Disolventes diferentes, obligatoriamente'],
   'Las soluciones isotónicas tienen la misma presión osmótica, es decir, concentraciones equivalentes de partículas disueltas.'),
  ('ad4ded15-6e19-4914-a977-c70f393ef7dd', 'en',
   'Saline solution, widely used in medicine, is an aqueous solution of:',
   array['Sodium chloride (NaCl) at a low concentration', 'Concentrated sulfuric acid', 'Pure ethyl alcohol', 'Oxygen gas dissolved in water'],
   'Physiological saline is a salt solution (0.9% NaCl), formulated to be isotonic with blood plasma.'),
  ('ad4ded15-6e19-4914-a977-c70f393ef7dd', 'es',
   'El suero fisiológico, muy usado en medicina, es una solución acuosa de:',
   array['Cloruro de sodio (NaCl) en baja concentración', 'Ácido sulfúrico concentrado', 'Alcohol etílico puro', 'Gas oxígeno disuelto en agua'],
   'El suero fisiológico es una solución salina (NaCl al 0,9%), formulada para ser isotónica respecto al plasma sanguíneo.')
) as v(id, locale, prompt, options, explanation)
join questions q
  on q.id = v.id::uuid
 and cardinality(q.options) = cardinality(v.options)
on conflict (question_id, locale) do update
  set prompt = excluded.prompt,
      options = excluded.options,
      explanation = excluded.explanation;
